CardSets.register({"id": "mushrooms", "name": "Mushrooms & Fungi", "code": "SHROOM", "description": "380 cards of the fungal kingdom — iconic toadstools, deadly amanitas, prized truffles, glowing species, medicinal molds and record-breaking fungi. Not plants at all.", "theme": {"primary": "#b33a2b", "secondary": "#4a3b28", "artBackground": "#f3ead8", "artFit": "cover"}, "pack": {"name": "Mushrooms Pack", "emblem": "🍄", "skin": "mushrooms", "slots": [{"count": 5, "label": "Common", "odds": {"common": 100}}, {"count": 2, "label": "Uncommon", "odds": {"uncommon": 100}}, {"count": 1, "label": "Wild card", "odds": {"common": 55, "uncommon": 30, "rare": 12, "epic": 3}}, {"count": 1, "label": "Rare or better (guaranteed)", "odds": {"rare": 81.8, "epic": 14, "legendary": 4, "chase": 0.2}}]}, "cards": [{"name": "Death Cap", "rarity": "chase", "id": "death-cap", "subtitle": "Species", "details": "Amanita phalloides: deadly poisonous; its amatoxins cause most fatal mushroom poisonings worldwide. Never eat it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita_phalloides_1.JPG?width=1024"}, {"name": "Fly Agaric", "rarity": "chase", "id": "fly-agaric", "subtitle": "Species", "details": "Amanita muscaria: the classic red toadstool. Toxic and psychoactive, packed with ibotenic acid and muscimol.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita_muscaria_Aberystwyth_2023.jpg?width=900"}, {"name": "Ghost Fungus", "rarity": "chase", "id": "ghost-fungus", "subtitle": "Species", "details": "Omphalotus nidiformis: an Australian fungus whose gills glow green in the dark — and which is poisonous to eat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Omphalotus_nidiformis_Binnamittalong_2_email.jpg?width=1024"}, {"name": "King Bolete", "rarity": "chase", "id": "king-bolete", "subtitle": "Species", "details": "Boletus edulis: the porcini — a prized edible bolete with a bun-like cap, thick stem and rich, nutty flavour.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Boletus_edulis_IT.jpg?width=1024"}, {"name": "Lion's Mane", "rarity": "chase", "id": "lions-mane", "subtitle": "Species", "details": "Hericium erinaceus: a white, icicle-toothed edible fungus that grows like a frozen waterfall on dead hardwood.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lion%27s-mane_mushroom_imported_from_iNaturalist_photo_29576097_on_21_March_2024.jpg?width=1024"}, {"name": "Matsutake", "rarity": "chase", "id": "matsutake", "subtitle": "Species", "details": "Tricholoma matsutake: a prized edible pine mushroom with a spicy, resinous scent, treasured in Japanese cooking.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Matsutake.jpg?width=1024"}, {"name": "Oregon Honey Fungus", "rarity": "chase", "id": "oregon-honey-fungus", "subtitle": "Species", "details": "Armillaria ostoyae: one Oregon genet covers some 2,385 acres of forest floor — the largest known organism on Earth.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Armillaria_ostoyae.jpg?width=1024"}, {"name": "Périgord Black Truffle", "rarity": "chase", "id": "perigord-black-truffle", "subtitle": "Truffle", "details": "Tuber melanosporum: the prized edible black truffle of Périgord, hunted underground beside oak and hazel roots.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Truffe_nature.JPG?width=1024"}, {"name": "True Morel", "rarity": "chase", "id": "true-morel", "subtitle": "Species", "details": "Morchella esculenta: a prized edible morel with a honeycombed cap; toxic raw, so it is always eaten cooked.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Morchella_esculenta_-_DE_-_TH_-_2013-05-01_-_01.JPG?width=1024"}, {"name": "Zombie-Ant Fungus", "rarity": "chase", "id": "zombie-ant-fungus", "subtitle": "Species", "details": "Ophiocordyceps unilateralis: infects ants, steers them to climb and bite a leaf, then sprouts from the body to spread spores.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ophiocordyceps_unilateralis.png?width=500"}, {"name": "Alba White Truffle", "rarity": "legendary", "id": "alba-white-truffle", "subtitle": "Truffle", "details": "Tuber magnatum: the edible white truffle of Alba, Italy — a marbled underground fungus hunted with dogs and among the priciest foods.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tuber%20magnatum.jpg?width=1024"}, {"name": "Almond Mushroom", "rarity": "legendary", "id": "almond-mushroom", "subtitle": "Species", "details": "Agaricus subrufescens: an edible cultivated Agaricus with a sweet almond scent, grown commercially in Brazil, Japan and China.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Agaricus%20subrufescens.jpg?width=1024"}, {"name": "Bear's Head Tooth", "rarity": "legendary", "id": "bears-head-tooth", "subtitle": "Species", "details": "Hericium americanum: an edible tooth fungus of eastern hardwood forests, hanging in branched clusters of long white icicle spines.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hericium%20americanum%20Ginns%20923240.jpg?width=1024"}, {"name": "Bleeding Tooth", "rarity": "legendary", "id": "bleeding-tooth", "subtitle": "Species", "details": "Hydnellum peckii: young caps ooze red, blood-like droplets; bitter and inedible, despite looking like a dessert.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hydnellum_peckii2.jpg?width=1024"}, {"name": "Caesar's Mushroom", "rarity": "legendary", "id": "caesars-mushroom", "subtitle": "Species", "details": "Amanita caesarea: an orange-capped edible Amanita prized since Roman times; choice when expertly identified, with poisonous lookalikes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita%20caesarea.JPG?width=1024"}, {"name": "Candy Cap", "rarity": "legendary", "id": "candy-cap", "subtitle": "Species", "details": "Lactarius rubidus: a small edible West Coast milkcap whose dried caps smell powerfully of maple syrup; used to flavour desserts.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius%20rubidus%2010671.jpg?width=1024"}, {"name": "Chaga", "rarity": "legendary", "id": "chaga", "subtitle": "Medicine", "details": "Inonotus obliquus: a black, charcoal-like birch parasite long brewed as a traditional medicinal tea in northern forests.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Inonotus_obliquus.jpg?width=1024"}, {"name": "Deadly Webcap", "rarity": "legendary", "id": "deadly-webcap", "subtitle": "Species", "details": "Cortinarius rubellus: deadly poisonous; its orellanine toxin can cause kidney failure days after it is eaten.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cortinarius_rubellus_01.jpg?width=1024"}, {"name": "Destroying Angel", "rarity": "legendary", "id": "destroying-angel", "subtitle": "Species", "details": "Amanita bisporigera: a pure-white, deadly poisonous Amanita; its amatoxins destroy the liver. Never eat it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita_bisporigera_17932.jpg?width=1024"}, {"name": "False Morel", "rarity": "legendary", "id": "false-morel", "subtitle": "Species", "details": "Gyromitra esculenta: a brain-like spring fungus that is poisonous and potentially deadly, despite its morel-like look.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fr%C3%BChjahrslorchel.JPG?width=1024"}, {"name": "Field Blewit", "rarity": "legendary", "id": "field-blewit", "subtitle": "Species", "details": "Collybia personata (syn. Lepista personata): an edible grassland blewit with a pale cap and vivid violet-blue stem; eaten cooked.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lepista%20personata.JPG?width=1024"}, {"name": "Funeral Bell", "rarity": "legendary", "id": "funeral-bell", "subtitle": "Species", "details": "Galerina marginata: a small brown wood-grower that is deadly poisonous, carrying the same amatoxins as the death cap.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Galerina_marginata_Point_Reyes.jpg?width=1024"}, {"name": "Golden Chanterelle", "rarity": "legendary", "id": "golden-chanterelle", "subtitle": "Species", "details": "Cantharellus cibarius: a golden, fruity-scented prized edible, with blunt wrinkles instead of true gills under its cap.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chanterelle_Cantharellus_cibarius.jpg?width=1024"}, {"name": "Green Elfcup", "rarity": "legendary", "id": "green-elfcup", "subtitle": "Species", "details": "Chlorociboria aeruginascens: a tiny cup fungus that stains oak blue-green — the prized 'green oak' of Tunbridge ware.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chlorociboria_aeruginascens-336907.jpg?width=1024"}, {"name": "Indigo Milk Cap", "rarity": "legendary", "id": "indigo-milk-cap", "subtitle": "Species", "details": "Lactarius indigo: a startling blue milk cap that bleeds blue latex and is edible when cooked; its gills green with age.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_indigo_48568_edit.jpg?width=1024"}, {"name": "Jack-o'-Lantern", "rarity": "legendary", "id": "jack-o-lantern", "subtitle": "Species", "details": "Omphalotus illudens: an orange cluster fungus that is poisonous; its gills can glow faintly green in darkness.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Jack_o%27_Lantern_Mushroom_Fungus.png?width=500"}, {"name": "Lobster Mushroom", "rarity": "legendary", "id": "lobster-mushroom", "subtitle": "Species", "details": "Hypomyces lactifluorum: an edible parasitic fungus that turns Russula hosts bright lobster-orange; avoid specimens with unknown hosts.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hypomyces%20lactifluorum%20%28Lobster%20mushroom%29.jpg?width=1024"}, {"name": "Panther Cap", "rarity": "legendary", "id": "panther-cap", "subtitle": "Species", "details": "Amanita pantherina: a brown-capped Amanita that is poisonous and psychoactive, with stronger effects than fly agaric.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita_pantherina_2013_G1.jpg?width=1024"}, {"name": "Reishi", "rarity": "legendary", "id": "reishi", "subtitle": "Medicine", "details": "Ganoderma lucidum: a glossy lacquered bracket used for centuries in East Asian traditional medicine; too woody to eat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ganoderma.lucidum.shanofee.png?width=1024"}, {"name": "Saffron Milk Cap", "rarity": "legendary", "id": "saffron-milk-cap", "subtitle": "Species", "details": "Lactarius deliciosus: a prized edible pine milkcap that bleeds carrot-orange latex and stains green where handled.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius%20deliciosus.jpg?width=1024"}, {"name": "Shiitake", "rarity": "legendary", "id": "shiitake", "subtitle": "Species", "details": "Lentinula edodes: a prized edible mushroom first cultivated on logs in East Asia, now grown worldwide for its savoury depth.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Shiitakegrowing.jpg?width=1024"}, {"name": "Turkey Tail", "rarity": "legendary", "id": "turkey-tail", "subtitle": "Medicine", "details": "Trametes versicolor: a thin, rainbow-zoned bracket studied for medicinal compounds; far too tough and papery to eat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Trametes_versicolor_G4_%281%29.JPG?width=1024"}, {"name": "Wine Cap Stropharia", "rarity": "legendary", "id": "wine-cap-stropharia", "subtitle": "Species", "details": "Stropharia rugosoannulata: a choice edible garden giant with wine-red caps, widely cultivated in woodchip beds; caps can reach 30 cm.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2011-05-19%20Stropharia%20rugosoannulata%20Farl.%20ex%20Murrill%20183478.jpg?width=1024"}, {"name": "Wood Blewit", "rarity": "legendary", "id": "wood-blewit", "subtitle": "Species", "details": "Collybia nuda (syn. Lepista nuda): a lilac-stemmed edible woodland agaric that must be cooked before eating; never eaten raw.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lepista%20nuda%20LC0372.jpg?width=1024"}, {"name": "Yellow Stainer", "rarity": "legendary", "id": "yellow-stainer", "subtitle": "Species", "details": "Agaricus xanthodermus: looks like a field mushroom but stains chrome-yellow and is poisonous to many who eat it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Agaricus_xanthodermus_section.jpg?width=800"}, {"name": "Apricot Jelly", "rarity": "epic", "id": "apricot-jelly", "subtitle": "Species", "details": "Guepinia helvelloides: a salmon-pink, tongue-shaped jelly fungus found on rotting conifer wood.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Guepinia_helvelloides_47030.jpg?width=1024"}, {"name": "Bitter Oyster", "rarity": "epic", "id": "bitter-oyster", "subtitle": "Species", "details": "Panellus stipticus: astringent little oyster-like caps whose gills in some strains glow faintly green in the dark.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Panellus%20stipticus%20108799037.jpg?width=1024"}, {"name": "Black Poplar Mushroom", "rarity": "epic", "id": "black-poplar-mushroom", "subtitle": "Species", "details": "Cyclocybe aegerita: an edible poplar-loving mushroom, also called pioppino, cultivated on logs and prized in Italian cooking.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Agrocybe%20aegerita.jpg?width=1024"}, {"name": "Black Trumpet", "rarity": "epic", "id": "black-trumpet", "subtitle": "Species", "details": "Craterellus cornucopioides: the horn of plenty — a dark, funnel-shaped prized edible, hard to spot in leaf litter.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Craterellus_cornucopioides_JPG1.jpg?width=1024"}, {"name": "Blue Oyster", "rarity": "epic", "id": "blue-oyster", "subtitle": "Species", "details": "Pleurotus ostreatus: the blue-grey young form of the common edible oyster mushroom, named for caps that fade to grey-brown with age.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pleurotus%20ostreatus%20JPG7.jpg?width=1024"}, {"name": "Button Mushroom", "rarity": "epic", "id": "button-mushroom", "subtitle": "Form", "details": "Agaricus bisporus, picked young and white: the button mushroom, the world's most widely cultivated edible fungus.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/ChampignonMushroom.jpg?width=1024"}, {"name": "Caterpillar Fungus", "rarity": "epic", "id": "caterpillar-fungus", "subtitle": "Medicine", "details": "Ophiocordyceps sinensis parasitises ghost-moth larvae high in the Himalayas; used in traditional Chinese medicine for centuries.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cordyceps%20sinensis.jpg?width=1024"}, {"name": "Cauliflower Fungus", "rarity": "epic", "id": "cauliflower-fungus", "subtitle": "Species", "details": "Sparassis crispa makes layered, noodle-like frills at conifer bases. A prized edible when young and fresh, it is eaten cooked.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Grote_sponszwam_%28Sparassis_crispa%29._09-11-2023._%28d.j.b%29.jpg?width=1024"}, {"name": "Chestnut Mushroom", "rarity": "epic", "id": "chestnut-mushroom", "subtitle": "Species", "details": "Pholiota adiposa: a golden, scaly Pholiota grown commercially as the edible chestnut mushroom, with a crisp, nutty texture.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Goudvliesbundelzwam.jpg?width=1024"}, {"name": "Chicken of the Woods", "rarity": "epic", "id": "chicken-of-the-woods", "subtitle": "Species", "details": "Laetiporus sulphureus: bright orange shelves on trees; eaten cooked when young, though it upsets some stomachs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Laetiporus_sulphureus_big.jpg?width=1024"}, {"name": "Cremini", "rarity": "epic", "id": "cremini", "subtitle": "Form", "details": "Agaricus bisporus, brown and picked mid-size: the cremini — between the white button and the big open portobello.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2016-01_Agaricus_bisporus_06.jpg?width=1024"}, {"name": "Crown-Tipped Coral", "rarity": "epic", "id": "crown-tipped-coral", "subtitle": "Species", "details": "Artomyces pyxidatus: a crown-tipped coral fungus, each branch tip ending in a tiny cup ringed with points.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Artomyces_pyxidatus.jpg?width=1024"}, {"name": "Elm Oyster", "rarity": "epic", "id": "elm-oyster", "subtitle": "Species", "details": "Hypsizygus ulmarius: a pale edible mushroom fruiting high on elm and beech trunks, often confused with true oyster mushrooms.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hypsizygus%20ulmarius%20%28Bull.%29%20Redhead%20383230.jpg?width=1024"}, {"name": "Enoki", "rarity": "epic", "id": "enoki", "subtitle": "Species", "details": "Flammulina velutipes group: grown in darkness it becomes pale, noodle-thin enoki, a staple edible of East Asian cooking.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/EnokitakeJapaneseMushroom32.jpg?width=1024"}, {"name": "Ergot and St Anthony's Fire", "rarity": "epic", "id": "ergot-st-anthonys-fire", "subtitle": "Lore", "details": "Ergot fungus on rye caused medieval outbreaks of burning pain and hallucinations, a sickness named St Anthony's Fire.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Claviceps%20purpurea%2047424140.jpg?width=1024"}, {"name": "Giant Puffball", "rarity": "epic", "id": "giant-puffball", "subtitle": "Species", "details": "Calvatia gigantea: a white, football-sized puffball, edible only when young and pure white throughout when cut open.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Giant_Puffball.jpg?width=1024"}, {"name": "Golden Oyster", "rarity": "epic", "id": "golden-oyster", "subtitle": "Species", "details": "Pleurotus citrinopileatus: a bright yellow edible oyster mushroom native to Asia, now widely cultivated and naturalised abroad.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pleurotus%20citrinopileatus%20at%20Chatama%27s%20home.jpg?width=1024"}, {"name": "Hedgehog Mushroom", "rarity": "epic", "id": "hedgehog-mushroom", "subtitle": "Species", "details": "Hydnum repandum: a pale woodland edible with soft spines, not gills, under its cap; sweet and nutty when cooked.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hedgehog_fungi2.jpg?width=1024"}, {"name": "Hen of the Woods", "rarity": "epic", "id": "hen-of-the-woods", "subtitle": "Species", "details": "Grifola frondosa: maitake, a prized edible cluster of frilly caps at oak bases, long cultivated in Japan.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Grifola_frondosa_%2829715305790%29.jpg?width=1024"}, {"name": "Honey Mushroom", "rarity": "epic", "id": "honey-mushroom", "subtitle": "Species", "details": "Armillaria mellea: a honey-coloured edible mushroom eaten only well cooked; a tree pathogen fruiting in dense clusters at trunk bases.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Armillaria%20mellea%2C%20Honey%20Fungus%2C%20UK%201.jpg?width=1024"}, {"name": "Humongous Fungus", "rarity": "epic", "id": "humongous-fungus-michigan", "subtitle": "Record", "details": "One Armillaria gallica near Crystal Falls, Michigan, spans about 90 acres, weighs roughly 400 tonnes and is estimated at 2,500 years old.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Armillaria_gallica_26659.jpg?width=1024"}, {"name": "Jelly Babies", "rarity": "epic", "id": "jelly-babies", "subtitle": "Species", "details": "Leotia viscosa: a dark-green jelly club with a slimy head and yellow stalk. Despite the candy name, it is inedible and best left alone.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Leotia_viscosa_539279562.jpg?width=1024"}, {"name": "King Trumpet", "rarity": "epic", "id": "king-trumpet", "subtitle": "Species", "details": "Pleurotus eryngii: the king oyster, a thick-stemmed edible mushroom of Mediterranean steppes, famed for its meaty texture.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Seta%20de%20cardo%20%28Pleurotus%20eryngii%29%2C%202012-10-03%2C%20DD%2001.JPG?width=1024"}, {"name": "Largest Fruit Body", "rarity": "epic", "id": "fomitiporia-ellipsoidea", "subtitle": "Record", "details": "A Phellinus ellipsoideus bracket on Hainan Island, China, measured 10.85 m long and an estimated 400-500 kg - the largest fungal fruit body recorded.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fomitiporia_ellipsoidea.jpg?width=1024"}, {"name": "Liberty Cap", "rarity": "epic", "id": "liberty-cap", "subtitle": "Lore", "details": "Psilocybe semilanceata, a small caramel grassland mushroom with a distinct nipple; it contains the psychoactive compound psilocybin.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Psilocybe%20semilanceata%206514.jpg?width=1024"}, {"name": "Mycena chlorophos", "rarity": "epic", "id": "mycena-chlorophos", "subtitle": "Species", "details": "Mycena chlorophos: a tropical bonnet whose mycelium and young caps emit a soft green bioluminescent glow.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mycena%20chlorophos.jpg?width=1024"}, {"name": "Nameko", "rarity": "epic", "id": "nameko", "subtitle": "Species", "details": "Pholiota nameko: a small amber edible mushroom with a gelatinous coating, cultivated in Japan for miso soup and nabemono.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pholiota%20nameko%20culture.JPG?width=1024"}, {"name": "Omphalotus japonicus", "rarity": "epic", "id": "omphalotus-japonicus", "subtitle": "Species", "details": "Omphalotus japonicus: a glowing, poisonous Japanese mushroom whose toxins cause severe stomach illness.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lampteromyces%20japonicus%201999%201022.jpg?width=1024"}, {"name": "Oyster Mushroom", "rarity": "epic", "id": "oyster-mushroom", "subtitle": "Species", "details": "Pleurotus ostreatus: a widely cultivated edible that fans off dead wood — and traps and eats nematode worms.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pleurotus_ostreatus_JPG7.jpg?width=1024"}, {"name": "Penicillin Mold", "rarity": "epic", "id": "penicillin-mold", "subtitle": "Medicine", "details": "Penicillium chrysogenum, the mould behind penicillin, the antibiotic whose discovery by Fleming in 1928 changed medicine.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Penicillium%20notatum.jpg?width=1024"}, {"name": "Phoenix Oyster", "rarity": "epic", "id": "phoenix-oyster", "subtitle": "Species", "details": "Pleurotus pulmonarius: the phoenix or lung oyster, a pale edible summer species fruiting in shelves on dead hardwood.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pleurotus%20pulmonarius%20LC0228.jpg?width=1024"}, {"name": "Pink Oyster", "rarity": "epic", "id": "pink-oyster", "subtitle": "Species", "details": "Pleurotus djamor: a vivid pink tropical oyster mushroom, grown commercially as an edible and quick to fruit in warm weather.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pleurotus%20djamor%20crop.jpg?width=1024"}, {"name": "Portobello", "rarity": "epic", "id": "portobello", "subtitle": "Form", "details": "Agaricus bisporus, grown fully open and brown: the portobello — the same species as the button mushroom, at full size.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Portobello_Champignon.jpg?width=1024"}, {"name": "Prototaxites", "rarity": "epic", "id": "prototaxites", "subtitle": "Record", "details": "Trunk-like fossils up to 8 m tall made this the largest land organism of its age; long read as a giant fungus, its identity is still debated.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Prototaxites_apex.jpg?width=1024"}, {"name": "Sheathed Woodtuft", "rarity": "epic", "id": "sheathed-woodtuft", "subtitle": "Species", "details": "Kuehneromyces mutabilis: an edible woodtuft fruiting in tufts on stumps — but dangerously similar to the deadly Galerina marginata.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stockschwaemmchen.jpg?width=1024"}, {"name": "Super Mushroom", "rarity": "epic", "id": "super-mushroom", "subtitle": "Lore", "details": "Mario's red-capped power-up, widely linked to the fly agaric; touching one makes the small plumber grow to full size.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Red%20Amanita%20muscaria%20mushrooms%20-%20Piorunka%2C%20Poland.jpg?width=1024"}, {"name": "Termitomyces titanicus", "rarity": "epic", "id": "termitomyces-titanicus", "subtitle": "Record", "details": "The largest edible mushroom known: grown by termites in Zambia and West Africa, its cap can reach 1 metre (3 ft) across.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Termitomyces_titanicus.jpg?width=1024"}, {"name": "Toothed Jelly", "rarity": "epic", "id": "toothed-jelly", "subtitle": "Species", "details": "Pseudohydnum gelatinosum: a translucent jelly fungus with tiny soft teeth, not gills, under its cap.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pseudohydnum_gelatinosum_Abernethy_Forest.jpg?width=1024"}, {"name": "Upright Coral", "rarity": "epic", "id": "upright-coral", "subtitle": "Species", "details": "Ramaria stricta: a tightly upright, tan coral fungus growing from buried wood, with repeated vertical branches.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ramaria_stricta_171867.jpg?width=1024"}, {"name": "Velvet Shank", "rarity": "epic", "id": "velvet-shank", "subtitle": "Species", "details": "Flammulina velutipes: a winter edible with a dark velvety stem, fruiting in frosty clusters on dead wood; the wild form of enoki.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2009-11-19%20Flammulina%20velutipes%20agg%20biolib.cz%20crop.jpg?width=1024"}, {"name": "Violet Coral", "rarity": "epic", "id": "violet-coral", "subtitle": "Species", "details": "Clavaria zollingeri: a rare violet coral fungus, branching like tiny purple antlers from forest floors.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Clavaria_zollingeri_90973.jpg?width=1024"}, {"name": "Witch's Butter", "rarity": "epic", "id": "witchs-butter", "subtitle": "Species", "details": "Tremella mesenterica: a golden, brain-like jelly that parasitises crust fungi living inside dead wood.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tremella_mesenterica_branch.JPG?width=1024"}, {"name": "Agarikon", "rarity": "rare", "id": "agarikon", "subtitle": "Medicine", "details": "Laricifomes officinalis, a long-lived conk on old conifers, was used in traditional medicine since ancient Greek times.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fomitopsis%20officinalis%20483579.jpg?width=1024"}, {"name": "Alba White Truffle Festival", "rarity": "rare", "id": "alba-white-truffle-festival", "subtitle": "Lore", "details": "Alba in Piedmont holds an international white truffle fair each autumn, with an auction and a market for Tuber magnatum.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/White%20truffles%20from%20Alba.jpg?width=1024"}, {"name": "Amethyst Deceiver", "rarity": "rare", "id": "amethyst-deceiver", "subtitle": "Species", "details": "Laccaria amethystina: a small, deep-violet edible deceiver that fades to buff as it dries out in the sun.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Laccaria_amethystina_-_Lak%C3%B3wka_ametystowa.jpg?width=1024"}, {"name": "Basket Fungus", "rarity": "rare", "id": "basket-fungus", "subtitle": "Species", "details": "Ileodictyon cibarium: New Zealand's basket fungus, a white geometric lattice ball blown free of its base.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Basket_Fungi._%2851221891653%29.jpg?width=1024"}, {"name": "Bay Bolete", "rarity": "rare", "id": "bay-bolete", "subtitle": "Species", "details": "Imleria badia: a chestnut-brown woodland bolete, a good edible whose pores bruise blue-green when pressed.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Boletus_badius_JPG1.jpg?width=1024"}, {"name": "Beech Mushroom", "rarity": "rare", "id": "beech-mushroom", "subtitle": "Species", "details": "Hypsizygus tessulatus: the beech mushroom or shimeji, a small edible species cultivated in clusters and sold across East Asia.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hypsizygus%20marmoreus.jpg?width=1024"}, {"name": "Beechwood Sickener", "rarity": "rare", "id": "beechwood-sickener", "subtitle": "Species", "details": "Russula nobilis: a red-capped beechwood brittlegill considered poisonous, causing gastrointestinal symptoms when eaten.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russ%20nobilis.jpg?width=1024"}, {"name": "Bianchetto Truffle", "rarity": "rare", "id": "bianchetto-truffle", "subtitle": "Truffle", "details": "Tuber borchii, the whitish truffle of Europe, is a smaller, garlicky edible cousin of the great white truffle of Alba.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tartufo%20marzuolo.jpg?width=500"}, {"name": "Bridal Veil Stinkhorn", "rarity": "rare", "id": "bridal-veil-stinkhorn", "subtitle": "Species", "details": "Phallus indusiatus: a tropical stinkhorn wearing a lacy white skirt, or indusium, below its cap.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Phallus_indusiatus_02.JPG?width=1024"}, {"name": "Brown Beech Mushroom", "rarity": "rare", "id": "brown-beech-mushroom", "subtitle": "Species", "details": "Hypsizygus tessulatus: the brown buna-shimeji strain of beech mushroom, an edible cultivated cluster mushroom with a nutty flavour.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hypsizygus%20tessulatus%20%282%29.jpg?width=1024"}, {"name": "Charcoal Burner", "rarity": "rare", "id": "charcoal-burner", "subtitle": "Species", "details": "Russula cyanoxantha: one of the few mild, edible Russula species, a purple-green brittlegill valued by European foragers.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russula%20cyanoxantha.JPG?width=1024"}, {"name": "Chernobyl Black Fungi", "rarity": "rare", "id": "chernobyl-black-fungi", "subtitle": "Record", "details": "Melanin-rich black fungi colonise Chernobyl's ruined reactor and are studied for growing toward radiation - a radiosynthesis idea still unproven.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chernobyl_reactor_4.jpg?width=1024"}, {"name": "Chinese Black Truffle", "rarity": "rare", "id": "chinese-black-truffle", "subtitle": "Truffle", "details": "Tuber indicum, an edible Asian black truffle exported worldwide; it resembles the Perigord truffle but with a milder aroma.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tuber%20indicum%20of%20jar.jpg?width=1024"}, {"name": "Clouded Agaric", "rarity": "rare", "id": "clouded-agaric", "subtitle": "Species", "details": "Clitocybe nebularis: the clouded funnel, once eaten but now considered inedible after causing gastrointestinal upsets in some people.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Nevelzwam%20%28nebularis%29%20tussen%20afgevallen%20beukenblad%20%28d.j.b.%29%2001.jpg?width=1024"}, {"name": "Collared Earthstar", "rarity": "rare", "id": "collared-earthstar", "subtitle": "Species", "details": "Geastrum triplex: an earthstar whose outer rays fold into a collar, lifting its spore ball like a trophy.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Geastrum_triplex_-_Bola_Creek.jpg?width=1024"}, {"name": "Common Ink Cap", "rarity": "rare", "id": "common-ink-cap", "subtitle": "Species", "details": "Coprinopsis atramentaria: an ink cap that is poisonous with alcohol — its coprine blocks alcohol breakdown for days.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Coprinopsis_atramentaria_3_-_Lindsey.jpg?width=1024"}, {"name": "Cordyceps militaris", "rarity": "rare", "id": "cordyceps-militaris", "subtitle": "Species", "details": "Cordyceps militaris: an orange club fungus that grows from buried insect pupae and is now widely cultivated.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2010-08-06_Cordyceps_militaris_1.jpg?width=800"}, {"name": "Crab Brittlegill", "rarity": "rare", "id": "crab-brittlegill", "subtitle": "Species", "details": "Russula xerampelina: an edible brittlegill that smells of crab or shrimp when cooked, with a cap that varies from red to purple.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2011-11-08%20Russula%20xerampelina%20%28Schaeff.%29%20Fr%20180998%20mod.jpg?width=1024"}, {"name": "Crystal Brain", "rarity": "rare", "id": "crystal-brain", "subtitle": "Species", "details": "Exidia nucleata: Crystal Brain, a clear jelly dotted with white chalky grains, on dead hardwood twigs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Crystal_Brain_Fungus_%28Exidia_nucleata%29_-_geograph.org.uk_-_1000447.jpg?width=1024"}, {"name": "Cyclosporine Fungus", "rarity": "rare", "id": "cyclosporine-fungus", "subtitle": "Medicine", "details": "Tolypocladium inflatum, a fungus of insect larvae, is the original source of ciclosporin, the transplant anti-rejection drug.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tolypocladium.jpg?width=1024"}, {"name": "Desert Truffle", "rarity": "rare", "id": "desert-truffle-terfezia", "subtitle": "Truffle", "details": "Terfezia claveryi is an edible desert truffle of arid lands around the Mediterranean, swelling after rare rains.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tirmania%20nivea%20et%20Trefezia%20claveryi%20%28Souk%20de%20Rissani%2C%20Maroc%29.jpg?width=1024"}, {"name": "Devil's Fingers", "rarity": "rare", "id": "devils-fingers", "subtitle": "Species", "details": "Clathrus archeri: Devil's Fingers, a stinkhorn whose red tentacle arms burst from a slimy white egg.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Clathrus_archeri.jpg?width=1024"}, {"name": "Dog Stinkhorn", "rarity": "rare", "id": "dog-stinkhorn", "subtitle": "Species", "details": "Mutinus caninus: a slender dog stinkhorn with an orange-red, slime-tipped spike rising from a white egg.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gemeine_Hundsrute_Mutinus_caninus.JPG?width=1024"}, {"name": "Earpick Fungus", "rarity": "rare", "id": "earpick-fungus", "subtitle": "Species", "details": "Auriscalpium vulgare is a tiny spine fungus on buried conifer cones, with a fuzzy cap on a slender stalk, like a miniature ear pick.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Auriscalpium_vulgare_129877.jpg?width=1024"}, {"name": "Elegant Stinkhorn", "rarity": "rare", "id": "elegant-stinkhorn", "subtitle": "Species", "details": "Mutinus elegans: an elegant pink-orange stinkhorn that leans as it rises from its volval egg in gardens.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mutinus_elegans_%28DG_9911_Type%29.jpg?width=1024"}, {"name": "Eternal Light Mycena", "rarity": "rare", "id": "eternal-light-mycena", "subtitle": "Species", "details": "Mycena luxaeterna: a Brazilian bonnet whose stem glows yellow-green all night, every night.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mycenaluxaeterna.jpg?width=1024"}, {"name": "First Eukaryote Genome", "rarity": "rare", "id": "yeast-genome-first", "subtitle": "Record", "details": "Baker's yeast, Saccharomyces cerevisiae, became the first eukaryote to have its whole genome sequenced, in 1996.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Saccharomyces_cerevisiae_SEM.jpg?width=1024"}, {"name": "Fu Ling", "rarity": "rare", "id": "fu-ling", "subtitle": "Medicine", "details": "Wolfiporia extensa grows a large underground sclerotium called fu ling, used in traditional Chinese medicine.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tuckahoe.jpg?width=1024"}, {"name": "Green Brittlegill", "rarity": "rare", "id": "green-brittlegill", "subtitle": "Species", "details": "Russula virescens: the quilted green russula, a prized edible brittlegill whose cap cracks into a green patchwork with age.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russula%20virescens3.JPG?width=1024"}, {"name": "Latticed Stinkhorn", "rarity": "rare", "id": "latticed-stinkhorn", "subtitle": "Species", "details": "Clathrus ruber: a latticed stinkhorn whose hollow red cage smells of carrion to attract spore-carrying flies.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Clathrus_ruber_spacepleb.jpg?width=1024"}, {"name": "Lilac Bonnet", "rarity": "rare", "id": "lilac-bonnet", "subtitle": "Species", "details": "Mycena pura: a lilac, radish-smelling bonnet that is toxic, containing small amounts of muscarine.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rettichhelmling002.JPG?width=1024"}, {"name": "Macrocybe titans", "rarity": "rare", "id": "macrocybe-titans", "subtitle": "Record", "details": "Among the largest gilled mushrooms, this tropical agaric of the Americas can produce pale caps reported up to about 1 metre across.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Macrocybe_titans_%28H.E._Bigelow_%26_Kimbr.%29_Pegler%2C_Lodge_%26_Nakasone_949069.jpg?width=1024"}, {"name": "Oak Mazegill", "rarity": "rare", "id": "oak-mazegill", "subtitle": "Species", "details": "Daedalea quercina grows thick, corky brackets on oak, its underside a maze of gill-like slots rather than round pores.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Daedalea_quercina_-_Eichen-Wirrling_-_oak_mazegill_-_maze-gill_fungus_-_d%C3%A9dal%C3%A9e_du_ch%C3%AAne_-_03.jpg?width=1024"}, {"name": "Oak Milk Cap", "rarity": "rare", "id": "oak-milk-cap", "subtitle": "Species", "details": "Lactarius quietus: an inedible oak milkcap with concentric zones and an oily, bug-like smell; common under oak in summer.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius%20quietus%202010%20G1%20crop.jpg?width=1024"}, {"name": "Ochre Brittlegill", "rarity": "rare", "id": "ochre-brittlegill", "subtitle": "Species", "details": "Russula ochroleuca: a common ochre-yellow brittlegill of woods and parks; mild forms are eaten, but it is poor and best avoided.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russula%20ochroleuca%20ch%C3%A2taigne.JPG?width=1024"}, {"name": "Oldest Fossil Mushroom", "rarity": "rare", "id": "gondwanagaricites", "subtitle": "Record", "details": "Gondwanagaricites magnificus, a 5 cm gilled mushroom mineralised in Brazilian limestone about 115 million years ago, is the oldest fossil mushroom.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amostra_fossilizada_do_cogumelo_Gondwanagaricites_magnificus.jpg?width=1024"}, {"name": "Orange Porecap", "rarity": "rare", "id": "orange-porecap", "subtitle": "Species", "details": "Favolaschia calocera: a bright orange porecap whose underside is a honeycomb of large open pores.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Favolaschia%20calocera.jpg?width=1024"}, {"name": "Oregon Black Truffle", "rarity": "rare", "id": "oregon-black-truffle", "subtitle": "Truffle", "details": "Leucangium carthusianum, a prized edible truffle dug from Douglas-fir forests in the Pacific Northwest, fruity and earthy.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Leucangium%20carthusianum%2017755.jpg?width=1024"}, {"name": "Oregon White Truffle", "rarity": "rare", "id": "oregon-white-truffle", "subtitle": "Truffle", "details": "Tuber oregonense, an edible white truffle of Pacific Northwest Douglas-fir woods, intensely garlicky and cheesy when ripe.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tuber%20oregonense%2035619.jpg?width=800"}, {"name": "Parasol Mushroom", "rarity": "rare", "id": "parasol-mushroom", "subtitle": "Species", "details": "Macrolepiota procera: a tall, drumstick-shaped edible parasol with a snakeskin-pattern stem and a movable ring.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Parasol-Macrolepiota-procera.jpg?width=1024"}, {"name": "Pecan Truffle", "rarity": "rare", "id": "pecan-truffle", "subtitle": "Truffle", "details": "Tuber lyonii grows under pecan and hickory trees in North America and is gathered as a mild, nutty edible truffle.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pecan%20truffle.png?width=500"}, {"name": "Pilobolus Cannon", "rarity": "rare", "id": "pilobolus-cannon", "subtitle": "Record", "details": "The dung fungus Pilobolus fires its spore cap in microseconds at over 20,000 G - among the fastest accelerations measured in nature.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pilobolus_sporangia.jpg?width=1024"}, {"name": "Pink Pinwheel", "rarity": "rare", "id": "pink-pinwheel", "subtitle": "Species", "details": "Marasmius haematocephalus: a delicate pink pinwheel mushroom on a wiry stem, found in leaf litter.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Marasmius%20haematocephalus%20%28Mont.%29%20Fr.%20%289519552672%29.jpg?width=1024"}, {"name": "Pixie's Parasol", "rarity": "rare", "id": "pixies-parasol", "subtitle": "Species", "details": "Mycena interrupta: a tiny Pixie's Parasol from Australasia, sky-blue and no wider than a fingernail.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mycena_interrupta.jpg?width=1024"}, {"name": "Primrose Brittlegill", "rarity": "rare", "id": "primrose-brittlegill", "subtitle": "Species", "details": "Russula sardonia: a purple-red brittlegill under pines with gills that weep primrose-yellow droplets; inedible and acrid.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russ.sard.jpg?width=1024"}, {"name": "Psilocybe cubensis", "rarity": "rare", "id": "psilocybe-cubensis", "subtitle": "Lore", "details": "A psilocybin-containing mushroom of warm, humid regions worldwide, growing on dung and rich soils; it bruises blue when handled.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Psilocybe%20Cubensis%20Imire%20%28Psilocybe%20Cubensis%20Zimbabwe%29%209.jpg?width=1024"}, {"name": "Rigidoporus ulmarius", "rarity": "rare", "id": "rigidoporus-ulmarius", "subtitle": "Record", "details": "A bracket at Kew in London reached 425 cm around, long held as the largest fungal fruit body before the Hainan giant surpassed it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Meripilaceae_-_Rigidoporus_ulmarius.JPG?width=1024"}, {"name": "Scarlet Elf Cup", "rarity": "rare", "id": "scarlet-elf-cup", "subtitle": "Species", "details": "Sarcoscypha austriaca: a brilliant scarlet winter cup on buried twigs, one of the first fungi of the year.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Sarcoscypha_austriaca_81949.jpg?width=1024"}, {"name": "Shaggy Mane", "rarity": "rare", "id": "shaggy-mane", "subtitle": "Species", "details": "Coprinus comatus: a tall white shaggy ink cap, edible when young, before its gills melt into black 'ink'.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Coprinus_comatus%2C_the_shaggy_ink_cap%2C_lawyer%27s_wig%2C_or_shaggy_mane_mushroom.jpg?width=1024"}, {"name": "Shaggy Parasol", "rarity": "rare", "id": "shaggy-parasol", "subtitle": "Species", "details": "Chlorophyllum rhacodes: a shaggy parasol, edible only thoroughly cooked — and it still upsets some stomachs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chlorophyllum_rhacodes_LC0093.jpg?width=1024"}, {"name": "Sky-Blue Mushroom", "rarity": "rare", "id": "sky-blue-mushroom", "subtitle": "Species", "details": "Entoloma hochstetteri: New Zealand's vivid sky-blue mushroom, featured on the country's fifty-dollar note.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Entoloma_hochstetteri_%28Reichardt%29_G._Stev_99860.jpg?width=1024"}, {"name": "Slippery Jack", "rarity": "rare", "id": "slippery-jack", "subtitle": "Species", "details": "Suillus luteus: a slippery-capped pine bolete, eaten after its slimy skin is peeled; a ring marks its stem.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Suillus_luteus_475376.jpg?width=1024"}, {"name": "Snow Fungus", "rarity": "rare", "id": "snow-fungus", "subtitle": "Species", "details": "Tremella fuciformis: a white, frilly jelly fungus eaten in sweet soups and used in traditional Chinese medicine.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tremella_fuciformis_337510.jpg?width=1024"}, {"name": "Teonanacatl", "rarity": "rare", "id": "teonanacatl", "subtitle": "Lore", "details": "Nahuatl for 'flesh of the gods': the name Aztec peoples gave psilocybin mushrooms used in sacred rituals.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Psilocybe.mexicana.Xico.JPG?width=1024"}, {"name": "The $330,000 Truffle", "rarity": "rare", "id": "most-expensive-truffle", "subtitle": "Record", "details": "A 1.5 kg Italian white truffle sold for $330,000 at a charity auction in 2007, among the highest prices ever paid for a single fungus.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Truffle_washed_and_cut.jpg?width=1024"}, {"name": "The Belfort Fairy Ring", "rarity": "rare", "id": "belfort-fairy-ring", "subtitle": "Record", "details": "One of the largest fairy rings known, formed by Infundibulicybe geotropa near Belfort, France, is about 600 m across and over 700 years old.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Infundibulicybe_geotropa_111105w.JPG?width=1024"}, {"name": "The Miller", "rarity": "rare", "id": "the-miller", "subtitle": "Species", "details": "Clitopilus prunulus: an edible mushroom smelling strongly of raw pastry or cucumber, with pink spores and decurrent gills.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Clitopilus%20prunulus%20-%20BC%2C%202024.jpg?width=1024"}, {"name": "The Penicillin Mould", "rarity": "rare", "id": "penicillin-discovery", "subtitle": "Record", "details": "In 1928 Alexander Fleming noticed a Penicillium mould killing bacteria - the observation that led to penicillin, the first widely used antibiotic.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Penicillium_notatum.jpg?width=1024"}, {"name": "The Sickener", "rarity": "rare", "id": "the-sickener", "subtitle": "Species", "details": "Russula emetica: a scarlet brittlegill that is poisonous raw, causing vomiting; its peppery flesh deters most foragers.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russula%20emetica%20in%20Poland.jpg?width=800"}, {"name": "The Truffle Hunt", "rarity": "rare", "id": "truffle-hunt", "subtitle": "Lore", "details": "Hunters follow trained dogs through oak woods at dawn; dogs are now favoured over pigs, which tend to eat the prize.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Caveurs%20de%20truffes%20dans%20le%20Gard.jpg?width=1024"}, {"name": "Tortotubus", "rarity": "rare", "id": "tortotubus", "subtitle": "Record", "details": "Tortotubus protuberans, a cord-forming microfossil about 440 million years old, is among the oldest known fungi and land organisms.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ornatifilum_lornensis.jpg?width=1024"}, {"name": "Trooping Funnel", "rarity": "rare", "id": "trooping-funnel", "subtitle": "Species", "details": "Infundibulicybe geotropa: a large, buff, edible funnel mushroom trooping in woodland rings; must be told apart from toxic Clitocybe.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Clitocybe%20geotropa%20JPG1.jpg?width=1024"}, {"name": "Verdigris Agaric", "rarity": "rare", "id": "verdigris-agaric", "subtitle": "Species", "details": "Stropharia aeruginosa: a slimy blue-green beauty; its edibility is disputed and many guides list it as poisonous.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stropharia.aeruginosa.-.lindsey.jpg?width=1024"}, {"name": "Violet Webcap", "rarity": "rare", "id": "violet-webcap", "subtitle": "Species", "details": "Cortinarius violaceus: a rare webcap that is deep violet all over — cap, gills, stem and even its flesh.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2008-08-22_Cortinarius_violaceus_%28L.%29_Gray_18241.jpg?width=1024"}, {"name": "Weeping Milk Cap", "rarity": "rare", "id": "weeping-milk-cap", "subtitle": "Species", "details": "Lactifluus volemus: an edible milkcap that weeps abundant white latex, smells faintly fishy, and stains brown where handled.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius%20volemus%2054887.jpg?width=1024"}, {"name": "White Beech Mushroom", "rarity": "rare", "id": "white-beech-mushroom", "subtitle": "Species", "details": "Hypsizygus tessulatus: the white bunapi strain of beech mushroom, bred in Japan from a brown shimeji exposed to ultraviolet light.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Shimeji%20mushroom.jpg?width=1024"}, {"name": "Wood Ear", "rarity": "rare", "id": "wood-ear", "subtitle": "Species", "details": "Auricularia auricula-judae: a rubbery, ear-shaped jelly fungus, a classic edible texture in East Asian soups.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Jelly_Ear%2C_Auricularia_auricula-judae%2C_UK_2.jpg?width=1024"}, {"name": "Wrinkled Peach", "rarity": "rare", "id": "wrinkled-peach", "subtitle": "Species", "details": "Rhodotus palmatus: a rare, peach-pink mushroom with a wrinkled, netted cap on dead elm; bitter and inedible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rhodotus_palmatus2.jpg?width=1024"}, {"name": "1-Up Mushroom", "rarity": "uncommon", "id": "one-up-mushroom", "subtitle": "Lore", "details": "Mario's green mushroom grants an extra life; its colours invert the Super Mushroom's familiar red and white.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita%20muscaria%20%28green%29.JPG?width=1024"}, {"name": "Alice's Mushroom", "rarity": "uncommon", "id": "alices-mushroom", "subtitle": "Lore", "details": "In Alice's Adventures in Wonderland (1865), the Caterpillar sits on a mushroom whose sides make Alice grow or shrink.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Alice%20e%20a%20Lagarta.jpg?width=1024"}, {"name": "Appalachian Truffle", "rarity": "uncommon", "id": "appalachian-truffle", "subtitle": "Truffle", "details": "Tuber canaliculatum, the Appalachian truffle, is a large edible truffle native to eastern North American forests.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tuber%20canaliculatum%20%281%29.jpg?width=1024"}, {"name": "Artist's Bracket", "rarity": "uncommon", "id": "artists-bracket", "subtitle": "Species", "details": "Ganoderma applanatum: Artist's Bracket, whose white pore surface bruises brown and can be drawn upon.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ganoderma_applanatum_2010_G1.jpg?width=1024"}, {"name": "Baker's Yeast", "rarity": "uncommon", "id": "bakers-yeast", "subtitle": "Species", "details": "Saccharomyces cerevisiae, a single-celled fungus domesticated for bread, beer and wine over thousands of years.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Saccharomyces%20cerevisiae%2001.jpg?width=1024"}, {"name": "Beatrix Potter's Fungi", "rarity": "uncommon", "id": "beatrix-potter-fungi", "subtitle": "Lore", "details": "Before Peter Rabbit, Beatrix Potter painted hundreds of fungi watercolours and studied mushroom science seriously.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Beatrix%20Potter%20%27Toads%20Tea-party%27%20c.1905%20Bk%20of%20Rhymes%20%281917%29.jpg?width=900"}, {"name": "Beefsteak Polypore", "rarity": "uncommon", "id": "beefsteak-polypore", "subtitle": "Species", "details": "Fistulina hepatica: Beefsteak Polypore, a red, juice-weeping bracket on oak that looks like raw meat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fistulina_hepatica.JPG?width=1024"}, {"name": "Berkeley's Polypore", "rarity": "uncommon", "id": "berkeleys-polypore", "subtitle": "Species", "details": "Bondarzewia berkeleyi: Berkeley's Polypore, a giant fan-shaped rosette at the base of oaks.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bondarzewia_berkeleyi.jpg?width=1024"}, {"name": "Birch Bolete", "rarity": "uncommon", "id": "birch-bolete", "subtitle": "Species", "details": "Leccinum scabrum: a speckled-stemmed bolete found under birch, eaten well cooked; its cap runs grey to brown.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Birkenpilz01.jpg?width=1024"}, {"name": "Birch Brittlegill", "rarity": "uncommon", "id": "birch-brittlegill", "subtitle": "Species", "details": "Russula betularum: a small, pale pink brittlegill growing with birch; explicitly described as inedible in field guides.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russula%20betularum.jpg?width=1024"}, {"name": "Birch Polypore", "rarity": "uncommon", "id": "birch-polypore", "subtitle": "Species", "details": "Fomitopsis betulina: the birch polypore, a smooth bracket found almost only on dead or dying birch.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Piptoporus_betulinus_55.jpg?width=1024"}, {"name": "Black-Staining Polypore", "rarity": "uncommon", "id": "black-staining-polypore", "subtitle": "Species", "details": "Meripilus sumstinei: a huge clustered polypore at oak bases whose flesh stains black when handled.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Meripilus_sumstinei_354570.jpg?width=1024"}, {"name": "Blackfoot Polypore", "rarity": "uncommon", "id": "blackfoot-polypore", "subtitle": "Species", "details": "Polyporus varius: Blackfoot Polypore, an elegant funnel on twigs with a sharply black stem base.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2012-05-27%20Polyporus%20varius%20%28Pers.%29%20Fr.%201821%20%28Legitimate%3B%20MB225640%29%20222422.jpg?width=1024"}, {"name": "Bleeding Bonnet", "rarity": "uncommon", "id": "bleeding-bonnet", "subtitle": "Species", "details": "Mycena haematopus snaps open to bleed a dark red juice. It fruits in clusters on dead hardwood and is too insubstantial to eat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Haematopus-on-oak.jpg?width=1024"}, {"name": "Blusher", "rarity": "uncommon", "id": "blusher", "subtitle": "Species", "details": "Amanita rubescens: an Amanita whose flesh blushes pink when cut; toxic raw, eaten only thoroughly cooked.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita_rubescens.JPG?width=1024"}, {"name": "Blushing Bracket", "rarity": "uncommon", "id": "blushing-bracket", "subtitle": "Species", "details": "Daedaleopsis confragosa: Blushing Bracket, a tough thin bracket whose pores blush pink-brown when bruised.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Daedaleopsis%20confragosa%20111029981.jpg?width=1024"}, {"name": "Burgundy Truffle", "rarity": "uncommon", "id": "burgundy-truffle", "subtitle": "Truffle", "details": "Tuber uncinatum, the Burgundy truffle, is an autumn edible truffle with a stronger aroma than the summer truffle.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Truffes%20de%20Bourgogne%20-%20Tuber%20uncinatum.JPG?width=1024"}, {"name": "Butter Bolete", "rarity": "uncommon", "id": "butter-bolete", "subtitle": "Species", "details": "Butyriboletus appendiculatus: a firm, butter-yellow bolete of oak woods, rated a good edible when cooked.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Anh%C3%A4ngsel-R%C3%B6hrling_Boletus_appendiculatus.jpg?width=1024"}, {"name": "Camembert Mold", "rarity": "uncommon", "id": "camembert-mold", "subtitle": "Species", "details": "Penicillium camemberti grows the soft white rind of Camembert and Brie, ripening the cheese from the outside in.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/%2820251230%29%20Camembert%20cheese%2003.jpg?width=1024"}, {"name": "Camphor Fungus", "rarity": "uncommon", "id": "camphor-fungus", "subtitle": "Medicine", "details": "Taiwanofungus camphoratus grows only on Taiwan's camphor laurel and is used in Taiwanese traditional medicine.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/%E7%89%9B%E6%A8%9F%E8%8A%9D1.jpg?width=1024"}, {"name": "Cinnabar Bracket", "rarity": "uncommon", "id": "cinnabar-bracket", "subtitle": "Species", "details": "Trametes cinnabarina coats dead hardwood in small brackets of vivid vermilion-orange that fade buff with age and weather.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pycnoporus_cinnabarinus_%28Jacq.%29_P._Karst_153.jpg?width=1024"}, {"name": "Citrine Waxcap", "rarity": "uncommon", "id": "citrine-waxcap", "subtitle": "Species", "details": "Hygrocybe citrinovirens: a rare yellow-green waxcap of old, unfertilised grassland in Europe; edibility unknown.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hygrocybe%20citrinovirens%20MS7%20%284%29.jpg?width=1024"}, {"name": "Conical Waxcap", "rarity": "uncommon", "id": "conical-waxcap", "subtitle": "Species", "details": "Hygrocybe conica: the blackening waxcap, a yellow-orange cone that blackens with age or bruising; reported poisonous.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hygrocybe%20conica%20%282005%2011%2007%29%201.jpg?width=1024"}, {"name": "Conifer Mazegill", "rarity": "uncommon", "id": "conifer-mazegill", "subtitle": "Species", "details": "Gloeophyllum sepiarium: Conifer Mazegill, a rusty bracket with maze-like gills, common on fence posts.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gloeophyllum_sepiarium_qtl1.jpg?width=1024"}, {"name": "Cordyceps Diversity", "rarity": "uncommon", "id": "cordyceps-diversity", "subtitle": "Record", "details": "Cordyceps and its relatives number in the hundreds of species, each adapted to particular insect or fungal hosts around the world.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cordyceps%20tenuipes.jpg?width=1024"}, {"name": "Crimson Waxcap", "rarity": "uncommon", "id": "crimson-waxcap", "subtitle": "Species", "details": "Hygrocybe punicea: the largest waxcap, a deep crimson species of old grasslands; edibility unknown and not recommended as food.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Crimson%20Waxcap.%20Hygrocybe%20punicea%20%2849055268862%29.jpg?width=1024"}, {"name": "Crowded Brittlegill", "rarity": "uncommon", "id": "crowded-brittlegill", "subtitle": "Species", "details": "Russula densifolia: a white brittlegill that reddens, then blackens, with crowded gills; considered inedible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russula%20densifolia%20go%C5%82%C4%85bek%20g%C4%99stoblaszkowy%20BS11.JPG?width=1024"}, {"name": "Deer Shield", "rarity": "uncommon", "id": "deer-shield", "subtitle": "Species", "details": "Pluteus cervinus: an edible shield mushroom with a brown, deer-coloured cap and free pink gills, fruiting on stumps and buried wood.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rehbrauner%20Dachpilz%20Bruderwald-20251017-RM-164830.jpg?width=1024"}, {"name": "Devil's Bolete", "rarity": "uncommon", "id": "devils-bolete", "subtitle": "Species", "details": "Rubroboletus satanas: a chunky, red-pored bolete that is poisonous, causing severe stomach upset if eaten.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Boletus_satanas.JPG?width=1024"}, {"name": "Dryad's Saddle", "rarity": "uncommon", "id": "dryads-saddle", "subtitle": "Species", "details": "Cerioporus squamosus: Dryad's Saddle, a large scaly bracket on dead broadleaf wood, smelling of watermelon rind.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Polyporus_squamosus_Molter.jpg?width=1024"}, {"name": "Ectomycorrhiza", "rarity": "uncommon", "id": "ectomycorrhiza", "subtitle": "Form", "details": "In ectomycorrhiza a fungal sheath wraps a tree root tip and threads between its cells, trading mineral nutrients for sugars.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mycorrhizal_root_tips_%28amanita%29.jpg?width=1024"}, {"name": "Ergot Alkaloids", "rarity": "uncommon", "id": "ergot-alkaloids", "subtitle": "Medicine", "details": "The toxic alkaloids of Claviceps purpurea ergot were historically developed into medicines, despite ergot's danger in grain.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Claviceps%20purpurea.JPG?width=1024"}, {"name": "Fairy Ring", "rarity": "uncommon", "id": "fairy-ring-form", "subtitle": "Form", "details": "A ring of mushrooms marks the expanding edge of an underground mycelium, fruiting where the colony's growing front reaches fresh food.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fairy_ring_on_a_suburban_lawn_100_1851.jpg?width=1024"}, {"name": "Fairy Ring Mushroom", "rarity": "uncommon", "id": "fairy-ring-mushroom", "subtitle": "Species", "details": "Marasmius oreades: an excellent edible lawn mushroom fruiting in fairy rings — but easily confused with poisonous lookalikes.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Michigan%20Marasmius%20oreades.jpg?width=1024"}, {"name": "False Saffron Milk Cap", "rarity": "uncommon", "id": "false-saffron-milk-cap", "subtitle": "Species", "details": "Lactarius deterrimus: an edible spruce milkcap like the saffron milk cap, but its orange latex turns maroon, then green.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius-deterrimus-Fichten-Reizker.jpg?width=1024"}, {"name": "False Truffle", "rarity": "uncommon", "id": "false-truffle", "subtitle": "Truffle", "details": "Rhizopogon roseolus looks like a small potato underground; in Japan this false truffle is eaten as shoro.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2010-05-14%20Rhizopogon%20roseolus%201.jpg?width=1024"}, {"name": "False Turkey Tail", "rarity": "uncommon", "id": "false-turkey-tail", "subtitle": "Species", "details": "Stereum ostrea: False Turkey Tail, a golden crust fungus with a smooth, gill-less underside.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stereum_ostrea_146645.jpg?width=1024"}, {"name": "Fenugreek Milkcap", "rarity": "uncommon", "id": "fenugreek-milkcap", "subtitle": "Species", "details": "Lactarius helvus: a fenugreek- or curry-scented milkcap of boggy conifer woods; poisonous in quantity and considered inedible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius%20helvus%20-%20Lindsey.jpg?width=1024"}, {"name": "Field Mushroom", "rarity": "uncommon", "id": "field-mushroom", "subtitle": "Species", "details": "Agaricus campestris: the classic meadow mushroom, a good edible with pink gills that darken to chocolate brown.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Agaricus_campestris.jpg?width=1024"}, {"name": "Fragile Brittlegill", "rarity": "uncommon", "id": "fragile-brittlegill", "subtitle": "Species", "details": "Russula fragilis: a small, fragile purple-red brittlegill with a white stem; inedible and possibly poisonous.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russula%20fragilis.jpg?width=1024"}, {"name": "Fungi in Space", "rarity": "uncommon", "id": "fungi-in-space", "subtitle": "Record", "details": "Fungi live on space-station walls and have been grown in orbit, making them both research subjects and stubborn stowaways in space.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/The_station_pictured_from_the_SpaceX_Crew_Dragon_5.jpg?width=1024"}, {"name": "Fungi in the Deep Sea", "rarity": "uncommon", "id": "deep-sea-fungi", "subtitle": "Record", "details": "Living fungi have been recovered from deep-sea sediments kilometres below the ocean surface, in darkness, cold and crushing pressure.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/A_mussel%27s_life_around_deep-sea_hydrothermal_vents.jpg?width=1024"}, {"name": "Garlic Truffle", "rarity": "uncommon", "id": "garlic-truffle", "subtitle": "Truffle", "details": "Tuber macrosporum, the smooth black or garlic truffle, is a small edible European truffle with a garlicky scent.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tuber%20macrosporum%20486366.jpg?width=1024"}, {"name": "Giant Puffball Record", "rarity": "uncommon", "id": "giant-puffball-record", "subtitle": "Record", "details": "Record giant puffballs (Calvatia gigantea) have passed 2.6 m around and 20 kg; a Canadian champion held the edible-fungus size record for years.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Calvatia_gigantea_%2851422%29.jpg?width=1024"}, {"name": "Gilded Brittlegill", "rarity": "uncommon", "id": "gilded-brittlegill", "subtitle": "Species", "details": "Russula aurea: the gilded brittlegill, an uncommon edible red-capped Russula told apart by its golden-yellow flesh and mild taste.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rusaur2big.jpg?width=1024"}, {"name": "Gilled Polypore", "rarity": "uncommon", "id": "gilled-polypore", "subtitle": "Species", "details": "Lenzites betulina: the gilled polypore, a birch bracket whose underside bears true blade-like gills.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Trametes_betulina_California.jpg?width=1024"}, {"name": "Goblet Waxcap", "rarity": "uncommon", "id": "goblet-waxcap", "subtitle": "Species", "details": "Hygrocybe cantharellus: the goblet waxcap, a tiny orange-red species of mossy woods with widely spaced, decurrent gills.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2011-06-17%20Hygrocybe%20cantharellus%2069428%20cropped.jpg?width=1024"}, {"name": "Golden Waxcap", "rarity": "uncommon", "id": "golden-waxcap", "subtitle": "Species", "details": "Hygrocybe chlorophana: a slimy yellow-orange waxcap of grassy places; edibility unknown, like most small Hygrocybe species.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hygrocybe%20chlorophana.jpg?width=1024"}, {"name": "Griseofulvin Fungus", "rarity": "uncommon", "id": "griseofulvin-fungus", "subtitle": "Medicine", "details": "Penicillium griseofulvum gave science griseofulvin, an antifungal compound long used against ringworm infections.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Penicillium%20illustr.%202.png?width=1024"}, {"name": "Grisette", "rarity": "uncommon", "id": "grisette", "subtitle": "Species", "details": "Amanita vaginata: a ringless, grey-capped Amanita rising from a white sac; edible, but risky beside deadly kin.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/AmanitaVaginata2.jpg?width=1024"}, {"name": "Hairy Bracket", "rarity": "uncommon", "id": "hairy-bracket", "subtitle": "Species", "details": "Trametes hirsuta: Hairy Bracket, a small zoned bracket covered in coarse upright hairs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Trametes_hirsuta_BS14.2.jpg?width=1024"}, {"name": "Hairy Curtain Crust", "rarity": "uncommon", "id": "hairy-curtain-crust", "subtitle": "Species", "details": "Stereum hirsutum: Hairy Curtain Crust, tiny orange-yellow fluted shells with a hairy upper surface.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stereum_hirsutum_Aberystwyth_2024.jpg?width=1024"}, {"name": "Heath Waxcap", "rarity": "uncommon", "id": "heath-waxcap", "subtitle": "Species", "details": "Gliophorus laetus: a small orange-brown waxcap with decurrent gills and a burnt-rubber smell; edibility unknown, not eaten.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2009-06-06%20Hygrocybe%20laeta%202%2021847.jpg?width=1024"}, {"name": "Heaviest White Truffle", "rarity": "uncommon", "id": "heaviest-truffle", "subtitle": "Record", "details": "A white truffle unearthed in Italy weighed about 1.9 kg when found, among the heaviest white truffles ever recorded.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tuber_magnatum_Picco_690635.jpg?width=1024"}, {"name": "Hemlock Varnish Shelf", "rarity": "uncommon", "id": "hemlock-varnish-shelf", "subtitle": "Species", "details": "Ganoderma tsugae lacquers eastern hemlock in shiny red-brown shelves with a white growing edge, a close kin of reishi.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ganoderma_tsugae.jpg?width=1024"}, {"name": "Hexagonal-Pored Polypore", "rarity": "uncommon", "id": "hexagonal-pored-polypore", "subtitle": "Species", "details": "Neofavolus alveolaris: a small polypore named for its large, honeycomb-like hexagonal pores.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Polyporus_alveolaris.jpg?width=1024"}, {"name": "Hoof Fungus", "rarity": "uncommon", "id": "hoof-fungus", "subtitle": "Species", "details": "Fomes fomentarius: hoof fungus, a hard perennial bracket once processed into amadou tinder and felt.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fomes_fomentarius_2010_G2.jpg?width=1024"}, {"name": "Horse Mushroom", "rarity": "uncommon", "id": "horse-mushroom", "subtitle": "Species", "details": "Agaricus arvensis: a large, white meadow edible that smells faintly of anise and yellows slowly when bruised.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pieczarka_polowa_vongrzanka.JPG?width=1024"}, {"name": "Huitlacoche", "rarity": "uncommon", "id": "huitlacoche", "subtitle": "Species", "details": "Ustilago maydis turns maize kernels into swollen grey galls eaten in Mexico as huitlacoche, a prized delicacy.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Maisbeulenbrand%20Maisbrand%20Ustilago%20maydis.jpg?width=1024"}, {"name": "Koji Mold", "rarity": "uncommon", "id": "koji-mold", "subtitle": "Species", "details": "Aspergillus oryzae, the koji mould, ferments rice, soy and barley for sake, miso and soy sauce in Japan.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Aspergillus%20oryzae%20%28%E9%BA%B9%29.jpg?width=1024"}, {"name": "Larch Bolete", "rarity": "uncommon", "id": "larch-bolete", "subtitle": "Species", "details": "Suillus grevillei: a golden-yellow, slimy bolete that grows only with larch trees, edible after skinning.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Suill.grev.jpg?width=1024"}, {"name": "Lichen", "rarity": "uncommon", "id": "lichen", "subtitle": "Form", "details": "A lichen is a fungus farming algae or cyanobacteria inside its body - a symbiosis so complete it grows as a single crust, leaf or tuft.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Letharia_vulpina_JHollinger_crop.jpg?width=1024"}, {"name": "Lumpy Bracket", "rarity": "uncommon", "id": "lumpy-bracket", "subtitle": "Species", "details": "Trametes gibbosa: Lumpy Bracket, a thick pale bracket on beech, its cap often greened by algae.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Trametes_gibbosa_JPG1.jpg?width=1024"}, {"name": "Meadow Waxcap", "rarity": "uncommon", "id": "meadow-waxcap", "subtitle": "Species", "details": "Cuphophyllus pratensis: a large, salmon-buff meadow waxcap and one of the few waxcaps traditionally eaten; now declining in Europe.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2010-11-20%20Cuphophyllus%20pratensis.jpg?width=1024"}, {"name": "Mossy Maze Polypore", "rarity": "uncommon", "id": "mossy-maze-polypore", "subtitle": "Species", "details": "Cerrena unicolor brackets on dead hardwood often host algae that tint them green, and its underside ripens into a maze of pores.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cerrena_unicolor_45687.jpg?width=1024"}, {"name": "Mushroom Stones of Guatemala", "rarity": "uncommon", "id": "mushroom-stones-of-guatemala", "subtitle": "Lore", "details": "Ancient carved mushroom-shaped stones from highland Guatemala are linked by scholars to early ritual traditions.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pierre-champignon%20%28Guatemala%20-%20Maya%29.jpg?width=700"}, {"name": "Mycorrhizal Network", "rarity": "uncommon", "id": "mycorrhizal-network", "subtitle": "Form", "details": "Fungal threads link many plant roots underground, trading soil nutrients for plant sugars across a shared mycorrhizal network.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Vesicular_Arbuscular_Mycorrhizae_40X0031_07.jpg?width=1024"}, {"name": "Northern Tooth", "rarity": "uncommon", "id": "northern-tooth", "subtitle": "Species", "details": "Climacodon septentrionalis: Northern Tooth, tiered cream shelves packed with long, icicle-like spines.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Climacodon_septentrionalis_134149.jpg?width=1024"}, {"name": "Ochre Bracket", "rarity": "uncommon", "id": "ochre-bracket", "subtitle": "Species", "details": "Trametes ochracea: Ochre Bracket, a colourful zoned bracket in bands of orange, brown and cream.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Trametes%20ochracea%20169745771.jpg?width=1024"}, {"name": "Old Man of the Woods", "rarity": "uncommon", "id": "old-man-of-the-woods", "subtitle": "Species", "details": "Strobilomyces strobilaceus: a shaggy, pinecone-capped bolete; young specimens are edible but not highly rated.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Strobilomyces_floccopus_89374.jpg?width=1024"}, {"name": "Olive Oysterling", "rarity": "uncommon", "id": "olive-oysterling", "subtitle": "Species", "details": "Sarcomyxa serotina shelves off dead hardwood in late autumn, olive-green above and yellow-stemmed; once eaten, now treated with caution.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2012-10-16_Sarcomyxa_serotina_%28Pers.%29_P._Karst_272414.jpg?width=1024"}, {"name": "Orange Birch Bolete", "rarity": "uncommon", "id": "orange-birch-bolete", "subtitle": "Species", "details": "Leccinum versipelle: a bright orange-capped birch bolete, eaten cooked; its flesh slowly greys when cut.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Leccinum_versipelle_LC0366.jpg?width=1024"}, {"name": "Orange Grisette", "rarity": "uncommon", "id": "orange-grisette", "subtitle": "Species", "details": "Amanita crocea: a saffron-orange ringless amanita with a grooved cap edge and sack-like volva. Edible only thoroughly cooked; easily confused.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita_crocea_-_Lindsey.jpg?width=1024"}, {"name": "Paddy Straw Mushroom", "rarity": "uncommon", "id": "paddy-straw-mushroom", "subtitle": "Species", "details": "Volvariella volvacea: an edible mushroom grown on rice straw across Asia, picked young in its grey-brown egg stage.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/StrawMushroom.jpg?width=1024"}, {"name": "Parrot Waxcap", "rarity": "uncommon", "id": "parrot-waxcap", "subtitle": "Species", "details": "Gliophorus psittacinus: the parrot waxcap, slimy and green-stained like a parrot's plumage; considered inedible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hygrocybe%20psittacina%2054530.jpg?width=1024"}, {"name": "Pine Bolete", "rarity": "uncommon", "id": "pine-bolete", "subtitle": "Species", "details": "Boletus pinophilus: a mahogany-capped king among boletes, a prized edible found with pines and other trees.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Boletus_pinophilus3.JPG?width=1024"}, {"name": "Pine Bracket", "rarity": "uncommon", "id": "pine-bracket", "subtitle": "Species", "details": "Porodaedalea pini: a hard, hoof-shaped pine bracket and a cause of white pocket rot in living pines.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Phellinus_pini.jpg?width=1024"}, {"name": "Purple Brittlegill", "rarity": "uncommon", "id": "purple-brittlegill", "subtitle": "Species", "details": "Russula atropurpurea: a dark wine-purple brittlegill described as edible in guides, though Russula identification demands caution.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russ.atro.jpg?width=1024"}, {"name": "Red Yeast Rice", "rarity": "uncommon", "id": "red-yeast-rice", "subtitle": "Medicine", "details": "Monascus purpureus ferments rice red for food and tradition; it produces monacolin compounds studied by scientists.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Red%20yeast%20rice.jpg?width=1024"}, {"name": "Red-Cracking Bolete", "rarity": "uncommon", "id": "red-cracking-bolete", "subtitle": "Species", "details": "Xerocomellus chrysenteron: a small bolete whose olive cap cracks to show red flesh; edible but soft and mild.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Xerocomellus_chrysenteron28.jpg?width=1024"}, {"name": "Resinous Polypore", "rarity": "uncommon", "id": "resinous-polypore", "subtitle": "Species", "details": "Ischnoderma resinosum: Resinous Polypore, a dark bracket that in youth exudes amber droplets of liquid.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ischnoderma_resinosum_%28Fr.%29_Karst.jpg?width=1024"}, {"name": "Rhizomorphs", "rarity": "uncommon", "id": "rhizomorphs", "subtitle": "Form", "details": "Rhizomorphs are black, root-like cords of fused hyphae that let fungi like honey fungus travel through soil and climb under bark.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rhizomorphs_%28thick_fungal_threads%29_of_Armillaria_mellea_Lille_Northern_France_Bois_de_la_Citadelle_01.jpg?width=1024"}, {"name": "Roquefort Mold", "rarity": "uncommon", "id": "roquefort-mold", "subtitle": "Species", "details": "Penicillium roqueforti veins blue cheeses such as Roquefort, Stilton and Gorgonzola with sharp, tangy flavour.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Penicillium%20roqueforti.%20makro.%20I.JPG?width=1024"}, {"name": "Ruddy Truffle", "rarity": "uncommon", "id": "ruddy-truffle", "subtitle": "Truffle", "details": "Tuber rufum, the ruddy truffle, is a small reddish-brown European truffle with pale marbling in its dark flesh.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2016-11-10%20Tuber%20rufum%20Pico%20ex%20Fries%20687940.jpg?width=1024"}, {"name": "Sanghuang", "rarity": "uncommon", "id": "sanghuang", "subtitle": "Medicine", "details": "Phellinus linteus, called sanghuang, is a hard tree conk used in traditional East Asian medicine and studied by researchers.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/%E3%83%A1%E3%82%B7%E3%83%9E%E3%82%B3%E3%83%96%28Phellinus%20linteus%29.jpg?width=1024"}, {"name": "Scarlet Waxcap", "rarity": "uncommon", "id": "scarlet-waxcap", "subtitle": "Species", "details": "Hygrocybe coccinea: a small, brilliant scarlet waxcap of unimproved grassland; its edibility is doubtful and it is best left unpicked.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hygrocybe%20coccinea%20%281%29.jpg?width=1024"}, {"name": "Scarletina Bolete", "rarity": "uncommon", "id": "scarletina-bolete", "subtitle": "Species", "details": "Neoboletus luridiformis: red-pored and blue-bruising; poisonous raw, eaten only after thorough cooking.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Boletus_erythropus_2010_G3.jpg?width=1024"}, {"name": "Sclerotium", "rarity": "uncommon", "id": "sclerotium", "subtitle": "Form", "details": "A sclerotium is a hard, dark resting knot of packed hyphae that survives drought, cold or fire, then sprouts when conditions improve.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Claviceps_purpurea.JPG?width=1024"}, {"name": "Slender Brittlegill", "rarity": "uncommon", "id": "slender-brittlegill", "subtitle": "Species", "details": "Russula gracillima: a small, pale, long-stemmed brittlegill of birch woods; like most small Russula, treated as inedible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russula%20gracillima.jpg?width=1024"}, {"name": "Smoky Polypore", "rarity": "uncommon", "id": "smoky-polypore", "subtitle": "Species", "details": "Bjerkandera adusta: Smoky Polypore, a grey-zoned bracket with a smoky-grey pore surface on dead wood.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Bjerkandera.adusta.-.lindsey.jpg?width=1024"}, {"name": "Snowy Waxcap", "rarity": "uncommon", "id": "snowy-waxcap", "subtitle": "Species", "details": "Cuphophyllus virgineus: a white, waxy grassland mushroom, one of the commoner waxcaps and sometimes eaten, though best admired.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2007-10-20%20Cuphophyllus%20virgineus.jpg?width=1024"}, {"name": "Statin Fungus", "rarity": "uncommon", "id": "statin-fungus", "subtitle": "Medicine", "details": "Aspergillus terreus, a cinnamon-brown soil mould, is a natural source of lovastatin, the first widely used statin drug.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Aspergillus%20terreus.jpg?width=1024"}, {"name": "Stinkhorn Sprint", "rarity": "uncommon", "id": "stinkhorn-sprint", "subtitle": "Record", "details": "A common stinkhorn can erupt from its egg stage and reach full height within a few hours, one of the fastest growth spurts among mushrooms.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Phallus%20impudicus%2083566342.jpg?width=1024"}, {"name": "Stinking Dapperling", "rarity": "uncommon", "id": "stinking-dapperling", "subtitle": "Species", "details": "Lepiota cristata: a small, reddish-scaled dapperling considered poisonous, with a strong, unpleasant rubbery or garlicky smell.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2011-12-01%20Lepiota%20cristata%20%28Bolton%29%20P.%20Kumm%20186612.jpg?width=1024"}, {"name": "Suede Bolete", "rarity": "uncommon", "id": "suede-bolete", "subtitle": "Species", "details": "Xerocomus subtomentosus: a suede-textured, olive-brown bolete of broadleaf woods; edible but unremarkable.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ziegenlippe_Xerocomus_subtomentosus.jpg?width=1024"}, {"name": "Summer Truffle", "rarity": "uncommon", "id": "summer-truffle", "subtitle": "Truffle", "details": "Tuber aestivum, the summer truffle, is a mild, nutty edible truffle found under beech and oak across Europe.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tuber%20aestivum%20Valnerina%20014.jpg?width=1024"}, {"name": "Tawny Grisette", "rarity": "uncommon", "id": "tawny-grisette", "subtitle": "Species", "details": "Amanita fulva: a tawny, ringless amanita of woods and bogs. Potentially toxic raw and eaten only well cooked, it is not recommended.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita_fulva_lowpx.jpg?width=1024"}, {"name": "The Last of Us Cordyceps", "rarity": "uncommon", "id": "the-last-of-us-cordyceps", "subtitle": "Lore", "details": "The games and series imagine a fictional Cordyceps infecting people, inspired by the real fungus that controls ants.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Complex%20Ophiocordyceps%20unilateralis%20%28Zombie%20Ant%20Fungus%29.jpg?width=1024"}, {"name": "The Prince", "rarity": "uncommon", "id": "the-prince", "subtitle": "Species", "details": "Agaricus augustus: a big, scaly, almond-scented Agaricus, widely rated one of the finest edible wild mushrooms.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Agaricus_augustus_2011_G1.jpg?width=1024"}, {"name": "Truffle Hog", "rarity": "uncommon", "id": "truffle-hog", "subtitle": "Lore", "details": "Sows hunt truffles eagerly: ripe truffles release a scent like a boar pheromone, which the pigs are built to find.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Cochon%20truffier.JPG?width=1024"}, {"name": "Tuberous Polypore", "rarity": "uncommon", "id": "tuberous-polypore", "subtitle": "Species", "details": "Polyporus tuberaster: Tuberous Polypore, fruiting from a hard underground tuber-like sclerotium.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2026-07-24_Polyporus_tuberaster_%28Z5-10330E%29_by_Achim-Lammerts.jpg?width=1024"}, {"name": "Ugly Milkcap", "rarity": "uncommon", "id": "ugly-milkcap", "subtitle": "Species", "details": "Lactarius turpis: the ugly milkcap, an olive-brown, slimy birch species with dirty staining flesh; considered inedible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius%20turpis%202010%20G1.jpg?width=1024"}, {"name": "Umbrella Polypore", "rarity": "uncommon", "id": "umbrella-polypore", "subtitle": "Species", "details": "Polyporus umbellatus: the umbrella polypore, many small caps on branching stems from one underground base.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Polyporus_umbellatus.jpg?width=1024"}, {"name": "Violet-Toothed Polypore", "rarity": "uncommon", "id": "violet-toothed-polypore", "subtitle": "Species", "details": "Trichaptum biforme: a thin violet-toothed bracket whose toothed underside fades from purple to brown.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/TrichaptumBiformeTop.jpg?width=1024"}, {"name": "White Desert Truffle", "rarity": "uncommon", "id": "white-desert-truffle", "subtitle": "Truffle", "details": "Tirmania nivea, the white desert truffle, is eaten across North Africa and the Middle East after desert rains.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tirmania%20nivea%20%28Ain%20Chouater%2C%20Maroc%29.jpg?width=1024"}, {"name": "White-Pored Chicken", "rarity": "uncommon", "id": "white-pored-chicken", "subtitle": "Species", "details": "Laetiporus cincinnatus: a white-pored chicken fungus fruiting at tree bases, in rosettes on the ground.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2016-10-28%20Laetiporus%20cincinnatus%20%28Morgan%29%20Burdsall%2C%20Banik%2C%20%26%20Volk%20706825.jpg?width=1024"}, {"name": "Willow Shield", "rarity": "uncommon", "id": "willow-shield", "subtitle": "Species", "details": "Pluteus salicinus: a grey-green shield reported to contain psilocybin; a psychedelic woodland species, not a food mushroom.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2011-11-12%20Pluteus%20salicinus%20%28Pers.%29%20P.%20Kumm%20181966.jpg?width=1024"}, {"name": "Winter Truffle", "rarity": "uncommon", "id": "winter-truffle", "subtitle": "Truffle", "details": "Tuber brumale, the winter truffle, is a dark edible European truffle with a musky aroma, gathered in the cold months.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tuber%20brumale%20-%20Vue%20sur%20la%20tranche%20coup%C3%A9e.jpg?width=1024"}, {"name": "Woolly Milkcap", "rarity": "uncommon", "id": "woolly-milkcap", "subtitle": "Species", "details": "Lactarius torminosus: a pink, woolly-edged birch milkcap that is poisonous raw; eaten only after special preparation in parts of Europe.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius%20torminosus%20%283%29.JPG?width=1024"}, {"name": "Zombie Fungus Hosts", "rarity": "uncommon", "id": "zombie-fungus-hosts", "subtitle": "Record", "details": "Ophiocordyceps species manipulate ants, beetles, flies, wasps and more - a whole genus of parasites steering very different hosts.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Ant%20infected%20by%20Ophiocordyceps%20unilateralis.png?width=1024"}, {"name": "A Hundred Glowing Species", "rarity": "common", "id": "glowing-species-count", "subtitle": "Record", "details": "More than 100 fungal species are now known to glow green in the dark, from ghost fungus to tiny lantern Mycena species.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Omphalotus_nidiformis%2C_Ghost_Fungus%2C_Australia.jpg?width=1024"}, {"name": "Admirable Bolete", "rarity": "common", "id": "admirable-bolete", "subtitle": "Species", "details": "Aureoboletus mirabilis: a dark red-brown bolete fruiting on rotting hemlock wood, an odd habit for a bolete, with a sour, lemony taste.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Aureoboletus_mirabilis_101099123.jpg?width=800"}, {"name": "Aflatoxin Fungus", "rarity": "common", "id": "aflatoxin-fungus", "subtitle": "Species", "details": "Aspergillus flavus contaminates maize and peanuts and can produce aflatoxins, among the strongest natural toxins known.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Aspergillus%20flavus%2001.jpg?width=1024"}, {"name": "Almond Brittlegill", "rarity": "common", "id": "almond-brittlegill", "subtitle": "Species", "details": "Russula laurocerasi: Almond Brittlegill, a foetid-group russula smelling sweetly of almonds and cherries.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2010-09-06_Russula_laurocerasi_Melzer_122171.jpg?width=1024"}, {"name": "Amanita Christmas Ornament", "rarity": "common", "id": "amanita-christmas-ornament", "subtitle": "Lore", "details": "Glass fly agaric ornaments, a German Christmas tradition, hang on trees as symbols of luck and nature.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita%20Muscaria%20%2811248406913%29.jpg?width=1024"}, {"name": "American Yellow Morel", "rarity": "common", "id": "american-yellow-morel", "subtitle": "Species", "details": "Morchella americana: the classic eastern yellow morel of orchards and dying elms. Hollow and honeycombed; edible thoroughly cooked.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Morchella_americana_closer.JPG?width=1024"}, {"name": "Ascus", "rarity": "common", "id": "ascus", "subtitle": "Form", "details": "The ascus is a microscopic sac in which cup fungi, morels and truffles ripen their spores, often eight in a row, then fire them out.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Morelasci.jpg?width=1024"}, {"name": "Bakanae Fungus", "rarity": "common", "id": "bakanae-fungus", "subtitle": "Medicine", "details": "Gibberella fujikuroi causes bakanae disease of rice and produces gibberellins, plant hormones used in research.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gibberella%20fujikuroi.jpg?width=1024"}, {"name": "Ballerina Waxcap", "rarity": "common", "id": "ballerina-waxcap", "subtitle": "Species", "details": "Porpolomopsis calyptriformis: Ballerina Waxcap, a rare pink waxcap that splits like a dancer's skirt.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2007-10-06_Hygrocybe_calyptriformis_369513.jpg?width=1024"}, {"name": "Banded Mottlegill", "rarity": "common", "id": "banded-mottlegill", "subtitle": "Species", "details": "Panaeolus cinctulus: a compost and dung-heap mottlegill that contains psilocybin, a controlled psychoactive compound.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Panaeolus.subbalteatus.3.jpg?width=1024"}, {"name": "Basidium", "rarity": "common", "id": "basidium", "subtitle": "Form", "details": "The basidium is the microscopic club on gills, pores and teeth where most mushrooms make their spores, usually four at a time.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Basidium_schematic.svg?width=1024"}, {"name": "Beauveria", "rarity": "common", "id": "white-mold-beauveria", "subtitle": "Medicine", "details": "Beauveria bassiana coats insects in white mould and is used worldwide as a biological insecticide.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Beauveria.jpg?width=1024"}, {"name": "Berserker Fly Agaric Theory", "rarity": "common", "id": "berserker-fly-agaric-theory", "subtitle": "Lore", "details": "A debated theory once blamed fly agaric for Viking berserkers' fury; historians now find little evidence for it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Powerfull%20berserker%20viking%20warrior.jpg?width=1024"}, {"name": "Birch Milkcap", "rarity": "common", "id": "birch-milkcap", "subtitle": "Species", "details": "Lactarius tabidus: Birch Milkcap, a small carrot-brown milkcap whose white milk slowly yellows.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2007-08-25%20Lactarius%20tabidus%20Fr.jpg?width=1024"}, {"name": "Bitter Bolete", "rarity": "common", "id": "bitter-bolete", "subtitle": "Species", "details": "Tylopilus felleus: a porcini lookalike that is not poisonous but so intensely bitter it is considered inedible; note its pink pores.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tylopilus%20felleus%20060914c.jpg?width=1024"}, {"name": "Black Bread Mold", "rarity": "common", "id": "black-bread-mold", "subtitle": "Species", "details": "Rhizopus stolonifer is the fast black bread mould whose dark pins dot stale bread and soft fruit.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rhizopus%20stolonifer%201.jpg?width=1024"}, {"name": "Black Morel", "rarity": "common", "id": "black-morel", "subtitle": "Species", "details": "Morchella importuna: a dark-ridged black morel of gardens, mulch and burned ground. A prized edible when thoroughly cooked, never raw.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Morchella_importuna_211765.jpg?width=1024"}, {"name": "Boudier's Desert Truffle", "rarity": "common", "id": "boudiers-desert-truffle", "subtitle": "Truffle", "details": "Terfezia boudieri is an edible desert truffle of North Africa and the Middle East, swelling underground after seasonal rains.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Terfezia%20boudieri%20Trabut%20L%27Alg%C3%A9rie%20agricole%20en%201906.png?width=1024"}, {"name": "Brain False Truffle", "rarity": "common", "id": "brain-false-truffle", "subtitle": "Truffle", "details": "Hydnotrya cerebriformis is a wrinkled, brain-like underground fungus found in forests of Europe and Asia.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2011-10-21%20Hydnotrya%20cerebriformis%20%28Tul.%20%26%20C.%20Tul.%29%20Harkn%20314335.jpg?width=1024"}, {"name": "Brettanomyces", "rarity": "common", "id": "brettanomyces", "subtitle": "Species", "details": "Brettanomyces bruxellensis, the 'Brett' yeast, gives lambic beers and some wines their funky farmyard aromas.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Aspect%20de%20brettanomyces%20bruxellensis%20sur%20g%C3%A9lose%20YPD.JPG?width=1024"}, {"name": "Brown Roll-Rim", "rarity": "common", "id": "brown-roll-rim", "subtitle": "Species", "details": "Paxillus involutus: once widely eaten, this roll-rim can trigger a fatal immune attack on red blood cells. Deadly poisonous; never eat it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Navadne_podvihanke_(Paxillus_involutus).jpg?width=1024"}, {"name": "Butter Cap", "rarity": "common", "id": "butter-cap", "subtitle": "Species", "details": "Rhodocollybia butyracea: Butter Cap, a greasy-capped woodland mushroom with a swollen, club-like stem.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rhodocollybia_butyracea051207D.jpg?width=1024"}, {"name": "Butter Waxcap", "rarity": "common", "id": "butter-waxcap", "subtitle": "Species", "details": "Hygrocybe ceracea: Butter Waxcap, a small greasy yellow waxcap of short turf and mossy lawns.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hygrocybe%20ceracea%20237870982.jpg?width=1024"}, {"name": "Candlesnuff Fungus", "rarity": "common", "id": "candlesnuff-fungus", "subtitle": "Species", "details": "Xylaria hypoxylon: tiny black antlers with white tips on dead wood, like snuffed candle wicks; inedible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Geweihf%C3%B6rmige_Holzkeule_-_Staghorn_fungus_-_Xylaria_hypoxylon_-_01.jpg?width=1024"}, {"name": "Chicken Fat Mushroom", "rarity": "common", "id": "chicken-fat-mushroom", "subtitle": "Species", "details": "Suillus americanus: a slimy yellow bolete that grows with eastern white pine. Edible when cooked, though its slime upsets some stomachs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Suillus_americanus_Mt_Hood_Oregon.jpg?width=1024"}, {"name": "Chitin Walls", "rarity": "common", "id": "chitin-walls", "subtitle": "Form", "details": "Fungal cell walls are reinforced with chitin, the same tough material as insect shells - one reason fungi are closer kin to animals than plants.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chitin%20and%20Chitosan.jpg?width=1024"}, {"name": "Citric Acid Fungus", "rarity": "common", "id": "citric-acid-fungus", "subtitle": "Medicine", "details": "Aspergillus niger, a black mould, is used industrially to produce citric acid and enzymes for food and medicine.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Aspergillus%20niger%20Micrograph.jpg?width=1024"}, {"name": "Clustered Bonnet", "rarity": "common", "id": "clustered-bonnet", "subtitle": "Species", "details": "Mycena inclinata crowds oak stumps with bunched, bell-shaped caps that smell faintly of candle wax as they age.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mycena_inclinata%2C_Clustered_Bonnet%2C_UK.jpg?width=1024"}, {"name": "Coconut Milkcap", "rarity": "common", "id": "coconut-milkcap", "subtitle": "Species", "details": "Lactarius glyciosmus: Coconut Milkcap, a lilac-grey birch milkcap scented strongly of coconut.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2009-09-07%20Lactarius%20glyciosmus.jpg?width=1024"}, {"name": "Common Bonnet", "rarity": "common", "id": "common-bonnet", "subtitle": "Species", "details": "Mycena galericulata: a ribbed, grey-brown bonnet clustered on dead wood; too small and thin to be worth eating.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mycena_60303.jpg?width=1024"}, {"name": "Common Cavalier", "rarity": "common", "id": "common-cavalier", "subtitle": "Species", "details": "Melanoleuca polioleuca: a grey-brown meadow cavalier with crowded white gills, common on grassy road verges.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Melanoleuca_polioleuca_161115w.JPG?width=1024"}, {"name": "Common Conecap", "rarity": "common", "id": "common-conecap", "subtitle": "Species", "details": "Conocybe tenera: a tiny, fragile lawn conecap; some Conocybe are deadly poisonous, so it is never one to eat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Conocybe_tenera_by_Alan_Rockefeller.jpg?width=1024"}, {"name": "Common Dapperling", "rarity": "common", "id": "common-dapperling", "subtitle": "Species", "details": "Leucoagaricus leucothites: a smooth white lawn dapperling eaten by some, but dangerously confusable with deadly white Amanita species.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2009-10-23_Leucoagaricus_leucothites_(Vittad.)_M.M._Moser_ex_Bon_61894_crop.jpg?width=1024"}, {"name": "Common Earthball", "rarity": "common", "id": "common-earthball", "subtitle": "Species", "details": "Scleroderma citrinum: a tough, potato-like earthball that is poisonous; its inside ripens to purple-black dust.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Scleroderma_citrinum.jpg?width=1024"}, {"name": "Common Fieldcap", "rarity": "common", "id": "common-fieldcap", "subtitle": "Species", "details": "Agrocybe pediades: a small, yellow-brown lawn fieldcap of grass and mulch; not recommended as food.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Agrocybe_pediades_Baja_California.jpg?width=1024"}, {"name": "Common Funnel", "rarity": "common", "id": "common-funnel", "subtitle": "Species", "details": "Infundibulicybe gibba: the common funnel, a pale buff, funnel-capped mushroom of leaf litter in woods and gardens.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Clitocybe_gibba_060820w.jpg?width=1024"}, {"name": "Common Jellyspot", "rarity": "common", "id": "common-jellyspot", "subtitle": "Species", "details": "Dacrymyces stillatus: a tiny orange jelly blob on dead conifer wood, melting away and returning with the rain.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Dacrymyces_stillatus.jpg?width=1024"}, {"name": "Common Psathyrella", "rarity": "common", "id": "common-psathyrella", "subtitle": "Species", "details": "Psathyrella bipellis: a small, fragile brittlestem with a wine-red cap edge, growing in troops on woodland litter. Not considered edible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Psathyrella_bipellis.jpg?width=1024"}, {"name": "Common Puffball", "rarity": "common", "id": "common-puffball", "subtitle": "Species", "details": "Lycoperdon perlatum: a warty puffball, edible only while young and pure white inside; ripe, it puffs out spores.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Single_lycoperdon_perlatum.jpg?width=1024"}, {"name": "Common Stinkhorn", "rarity": "common", "id": "common-stinkhorn", "subtitle": "Species", "details": "Phallus impudicus: hatches from a 'witch's egg' into a foul, fly-covered spike that reeks of carrion.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Phallus_impudicus_LC0235.jpg?width=1024"}, {"name": "Corpse Finder Fungus", "rarity": "common", "id": "corpse-finder-fungus", "subtitle": "Lore", "details": "Hebeloma aminophilum fruits near animal remains in Australia, earning the grim nickname corpse finder.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hebeloma%20aminophilum.jpg?width=1024"}, {"name": "Deer Truffle", "rarity": "common", "id": "deer-truffle", "subtitle": "Truffle", "details": "Elaphomyces granulatus, the deer truffle, fruits underground and is dug and eaten by deer, squirrels and other wildlife.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/ElaphomycesGranulatus.jpg?width=1024"}, {"name": "Dripping Bonnet", "rarity": "common", "id": "dripping-bonnet", "subtitle": "Species", "details": "Roridomyces roridus coats its slender stem in clear slime, so the whole tiny bonnet glistens as if dripping wet on rotten conifer wood.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Roridomyces_roridus_Sonoma.jpg?width=1024"}, {"name": "Fairy Inkcap", "rarity": "common", "id": "fairy-inkcap", "subtitle": "Species", "details": "Coprinellus disseminatus fruits in dense troops of tiny grey-brown bells on stumps and buried wood; too small and insubstantial to eat.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Coprinellus%20disseminatus%20B%C5%BB5.jpg?width=1024"}, {"name": "Fairy Ring Folklore", "rarity": "common", "id": "fairy-ring-folklore", "subtitle": "Lore", "details": "Rings of mushrooms on lawns were long said to mark where fairies danced at night, and stepping inside was risky.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Weidekringzwam%20%28Marasmius%20oreades%29.%20Locatie%2C%20Paddenstoelenreservaat.%2031-10-2022.%20%28actm.%29%2002.jpg?width=1024"}, {"name": "Farming Before Humans", "rarity": "common", "id": "termite-fungus-farming", "subtitle": "Record", "details": "Fungus-growing termites have tended Termitomyces gardens for roughly 30 million years - agriculture far older than humanity itself.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Termitomyces_reticulatus_37340.jpg?width=1024"}, {"name": "Fatal Dapperling", "rarity": "common", "id": "fatal-dapperling", "subtitle": "Species", "details": "Lepiota subincarnata: a small pinkish-brown dapperling packed with deadly amatoxins. Deadly poisonous; never eat it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lepiota_subincarnata_117620.jpg?width=1024"}, {"name": "First Cultivated Mushroom", "rarity": "common", "id": "first-cultivated-mushroom", "subtitle": "Record", "details": "Wood ear (Auricularia) was grown on logs in China over a thousand years ago and is among the earliest mushrooms ever cultivated.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Wood%20ear%20mushroom%20farm.jpg?width=1024"}, {"name": "Fly Agaric and Santa", "rarity": "common", "id": "fly-agaric-and-santa", "subtitle": "Lore", "details": "A popular theory links Santa's red and white, flying reindeer and chimney visits to Siberian fly agaric traditions.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rangifer%20tarandus%2C%20Duisburg%20%28DE%29%20--%202023%20--%200299.jpg?width=1024"}, {"name": "Fool's Conecap", "rarity": "common", "id": "fools-conecap", "subtitle": "Species", "details": "Conocybe filaris: a small brown lawn mushroom carrying the same deadly amatoxins as the death cap. Deadly poisonous; never eat it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pholiotina_rugosa_62373.jpg?width=1024"}, {"name": "Frost's Bolete", "rarity": "common", "id": "frosts-bolete", "subtitle": "Species", "details": "Exsudoporus frostii: a striking red-pored bolete with a netted stalk that bruises blue and weeps amber droplets when young.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Exsudoporus_frostii_100632.jpg?width=1024"}, {"name": "Gemmed Amanita", "rarity": "common", "id": "gemmed-amanita", "subtitle": "Species", "details": "Amanita gemmata: a pale yellow amanita dotted with white warts. Toxic and psychoactive, it has poisoned people who mistook it for edibles.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita_gemmata_von_hms.jpg?width=900"}, {"name": "Geotrichum", "rarity": "common", "id": "geotrichum", "subtitle": "Species", "details": "Geotrichum candidum helps ripen soft cheeses, giving some rinds their wrinkled, brain-like surface.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Geotrichum%20candidum%2001.jpg?width=1024"}, {"name": "Gilded Bolete", "rarity": "common", "id": "gilded-bolete", "subtitle": "Species", "details": "Aureoboletus gentilis: a rare European oak bolete with a pinkish cap and golden-yellow pores that do not bruise blue.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Vrbenské_rybníky_-_Aureoboletus_gentilis_02.jpg?width=1024"}, {"name": "Gills", "rarity": "common", "id": "gills", "subtitle": "Form", "details": "Gills are thin blades under a cap that multiply the spore-bearing surface; a large mushroom can pack metres of gill edge into one cap.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lact.sub.jpg?width=1024"}, {"name": "Golden Milkcap", "rarity": "common", "id": "golden-milkcap", "subtitle": "Species", "details": "Lactarius chrysorrheus: a peachy milkcap whose white milk turns sulphur-yellow in minutes. Poisonous, causing stomach upset.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lact.chry.jpg?width=1024"}, {"name": "Grape Truffle Fungus", "rarity": "common", "id": "grape-truffle-fungus", "subtitle": "Truffle", "details": "Gautieria morchelliformis is a truffle-like underground fungus with folded chambers; despite the nickname, no true truffle.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gautieria%20morchelliformis.jpg?width=1024"}, {"name": "Green-Spored Lepiota", "rarity": "common", "id": "green-spored-lepiota", "subtitle": "Species", "details": "Chlorophyllum molybdites: the green-gilled false parasol of lawns. Poisonous, and the most commonly eaten toxic mushroom in North America.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Chlorophyllum_molybdites_Guadalajara.jpg?width=1024"}, {"name": "Grey Milkcap", "rarity": "common", "id": "grey-milkcap", "subtitle": "Species", "details": "Lactarius vietus: Grey Milkcap, a birch milkcap whose milk dries grey-green on the gills.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius%20vietus%2013067268.jpg?width=1024"}, {"name": "Hairy Genea", "rarity": "common", "id": "hairy-genea", "subtitle": "Truffle", "details": "Genea hispidula is a tiny, dark, hairy underground truffle-like fungus of European woodlands.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Genea%20hispidula%2040613.jpg?width=1024"}, {"name": "Half-Free Morel", "rarity": "common", "id": "half-free-morel", "subtitle": "Species", "details": "Morchella populiphila: a western half-free morel, its honeycombed cap attached only halfway down the stalk. Edible when thoroughly cooked.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Morchella_populiphila_320850.jpg?width=1024"}, {"name": "Hare's Foot Ink Cap", "rarity": "common", "id": "hares-foot-ink-cap", "subtitle": "Species", "details": "Coprinopsis lagopus: Hare's Foot Ink Cap, a fleeting white-woolly inkcap that may last only a few hours.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hasenpfoten.jpg?width=1024"}, {"name": "Hollow Bolete", "rarity": "common", "id": "hollow-bolete", "subtitle": "Species", "details": "Suillus cavipes: a larch bolete with a dry brown cap and a stalk that hollows with age. Edible when cooked, though little collected.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Boletus_cavipes.jpg?width=1024"}, {"name": "Hyphae", "rarity": "common", "id": "hyphae", "subtitle": "Form", "details": "Hyphae are the microscopic, branching tubes that build every fungus, tipped with growth and divided in many species by cross-walls.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Penicillium.jpg?width=1024"}, {"name": "John Cage the Mycologist", "rarity": "common", "id": "john-cage-mycology", "subtitle": "Lore", "details": "Composer John Cage was a serious amateur mycologist who co-founded the New York Mycological Society.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/John%20Cage%20%281988%29.jpg?width=1024"}, {"name": "Mica Cap", "rarity": "common", "id": "mica-cap", "subtitle": "Species", "details": "Coprinellus micaceus: Mica Cap, a clustered inkcap whose young cap glitters with mica-like granules.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Coprinellus_micaceus_Glimmer-Tintling.jpg?width=1024"}, {"name": "Millions Still Undescribed", "rarity": "common", "id": "millions-undescribed", "subtitle": "Record", "details": "Scientists estimate 2.2 to 3.8 million fungal species exist, yet only about 150,000 have been formally described so far.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Fungi_collage.jpg?width=1024"}, {"name": "Mycelium", "rarity": "common", "id": "mycelium", "subtitle": "Form", "details": "The mycelium is the fungus itself: a feeding web of threads spread through soil, wood or dung, of which mushrooms are only the fruit.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mushroom%27s_roots_%28myc%C3%A9lium%29.jpg?width=1024"}, {"name": "Nitrous Bonnet", "rarity": "common", "id": "nitrous-bonnet", "subtitle": "Species", "details": "Mycena leptocephala smells of bleach or nitric acid when crushed, a small grey-brown bonnet on woodland litter and old wood.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mycena_leptocephala_349379290.jpg?width=800"}, {"name": "Oregon Spring Truffle", "rarity": "common", "id": "oregon-spring-truffle", "subtitle": "Truffle", "details": "Tuber gibbosum, an edible white truffle of the Pacific Northwest, fruits in spring under Douglas-fir.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tuber%20gibbosum%2085547.jpg?width=1024"}, {"name": "Painted Suillus", "rarity": "common", "id": "painted-suillus", "subtitle": "Species", "details": "Suillus spraguei: a pine bolete with a shaggy red-scaled cap and yellow pores, once called the painted bolete. Edible when cooked.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Suillus_spraguei_58269.jpg?width=1024"}, {"name": "Partial Veil", "rarity": "common", "id": "partial-veil", "subtitle": "Form", "details": "A partial veil stretches from cap edge to stem, sheltering young gills; it tears as the cap opens, often leaving a ring behind.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2016-01_Agaricus_bisporus_07.jpg?width=1024"}, {"name": "Pecan Candy Cap", "rarity": "common", "id": "pecan-candy-cap", "subtitle": "Species", "details": "Lactarius rufulus: a reddish-brown candy cap of western oaks; dried, it smells of maple syrup and is used as a sweet flavouring.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_rufulus_Escondido.jpg?width=1024"}, {"name": "Peppery Milkcap", "rarity": "common", "id": "peppery-milkcap", "subtitle": "Species", "details": "Lactifluus piperatus: a big white milkcap with fiercely peppery milk; dried and ground as a pepper seasoning, and eaten cooked in some regions.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lactarius_piperatus_98569.jpg?width=1024"}, {"name": "Petticoat Mottlegill", "rarity": "common", "id": "petticoat-mottlegill", "subtitle": "Species", "details": "Panaeolus papilionaceus: a small dung-and-compost mottlegill once rumoured psychoactive; studies found no psilocybin in it. Not edible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Panaeolus_papilionaceus_California.jpg?width=1024"}, {"name": "Pig Truffle", "rarity": "common", "id": "pig-truffle", "subtitle": "Truffle", "details": "Choiromyces venosus, the pig truffle, is a pale false truffle reported to cause stomach upsets; it is not eaten.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Stachelsporige%20M%C3%A4andertr%C3%BCffel%20Choiromyces%20maeandriformis%201.jpg?width=1024"}, {"name": "Pinecone Cap", "rarity": "common", "id": "pinecone-cap", "subtitle": "Species", "details": "Strobilurus tenacellus springs from buried pine cones in spring, its little brown cap fed by threads running down to the cone.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2012-04-22_Strobilurus_tenacellus_%28Pers.%29_Singer_214245.jpg?width=1024"}, {"name": "Pleated Ink Cap", "rarity": "common", "id": "pleated-ink-cap", "subtitle": "Species", "details": "Parasola plicatilis: Pleated Ink Cap, a tiny pleated parasol on lawns that opens at dawn and folds by noon.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Parasola%20plicatilis%205463533.jpg?width=1024"}, {"name": "Plums and Custard", "rarity": "common", "id": "plums-and-custard", "subtitle": "Species", "details": "Tricholomopsis rutilans: a plum-red and yellow mushroom on pine stumps; once listed edible, now generally treated as inedible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Trichol%20rutilans02%20Alberto%20V%C3%A1zquez.JPG?width=1024"}, {"name": "Pores", "rarity": "common", "id": "pores", "subtitle": "Form", "details": "Boletes bear spores inside packed vertical tubes that open as pores - a spongy underside instead of blade-like gills.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tylopilus_felleus_pores.jpg?width=1024"}, {"name": "Probiotic Yeast", "rarity": "common", "id": "probiotic-yeast", "subtitle": "Medicine", "details": "Saccharomyces boulardii is a yeast used as a probiotic, first isolated from lychee fruit in Indochina.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Saccharomyces%20boulardii.jpg?width=1024"}, {"name": "Rhynie Chert Fungi", "rarity": "common", "id": "rhynie-chert-fungi", "subtitle": "Record", "details": "Scotland's roughly 410-million-year-old Rhynie chert preserves fungi living inside early land plants, an ancient partnership in stone.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rhynie_Chert_flora.jpg?width=1024"}, {"name": "Ring (Annulus)", "rarity": "common", "id": "annulus", "subtitle": "Form", "details": "The annulus is a skirt of tissue left on the stem when a partial veil tears away as the cap expands - a key clue in Amanita species.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gymnopilus_junonius-02.jpg?width=1024"}, {"name": "Rufous Milkcap", "rarity": "common", "id": "rufous-milkcap", "subtitle": "Species", "details": "Lactarius rufus: Rufous Milkcap, a red-brown pine milkcap whose white milk turns fiercely peppery.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lact.ruf.jpg?width=1024"}, {"name": "Russet Toughshank", "rarity": "common", "id": "russet-toughshank", "subtitle": "Species", "details": "Gymnopus dryophilus: Russet Toughshank, a common small brown mushroom with crowded white gills, in leaf litter.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Collybia_dryophila_20061001w.jpg?width=1024"}, {"name": "Sand Truffle", "rarity": "common", "id": "sand-truffle", "subtitle": "Truffle", "details": "Terfezia arenaria is an edible desert truffle of sandy soils around the western Mediterranean, dug after rains.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2002-03-13%20Terfezia%20arenaria%2018613.jpg?width=1024"}, {"name": "Saprotroph", "rarity": "common", "id": "saprotroph", "subtitle": "Form", "details": "Saprotroph fungi feed on the dead - wood, leaves, dung - digesting them externally and returning their nutrients to the soil.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Labagh_Woods_Bracket_Fungi_on_Fallen_Tree_II_2020-05-1816.jpg?width=1024"}, {"name": "Scaly Agaricus", "rarity": "common", "id": "scaly-agaricus", "subtitle": "Species", "details": "Agaricus placomyces: a flat-topped, brown-scaled woodland Agaricus smelling of phenol. Poisonous, causing gastrointestinal upset.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Agaricus_placomyces.jpg?width=1024"}, {"name": "Scarlet Bracket", "rarity": "common", "id": "scarlet-bracket", "subtitle": "Species", "details": "Pycnoporus sanguineus paints tropical dead wood with thin brackets of brilliant blood-orange that keep their colour when dried.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Pycnoporus_sanguineus_%28Polyporaceae%29_%2819032702868%29.jpg?width=800"}, {"name": "Shoyu Koji", "rarity": "common", "id": "shoyu-koji", "subtitle": "Species", "details": "Aspergillus sojae is the domesticated koji mould used to ferment soy sauce and miso in Japan.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Shoyukoji.jpg?width=1024"}, {"name": "Slimy Waxcap", "rarity": "common", "id": "slimy-waxcap", "subtitle": "Species", "details": "Gliophorus irrigatus: Slimy Waxcap, a grey-brown waxcap coated in a thick, slippery slime.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Gliophorus%20irrigatus%20%28Pers.%29%20A.M.%20Ainsw.%20%26%20P.M.%20Kirk%20250273.jpg?width=1024"}, {"name": "Small Stagshorn", "rarity": "common", "id": "small-stagshorn", "subtitle": "Species", "details": "Calocera cornea dots dead hardwood with tiny orange-yellow horns barely a centimetre tall, a jelly fungus easy to overlook.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Calocera_cornea_38121.jpg?width=1024"}, {"name": "Snowy Bonnet", "rarity": "common", "id": "snowy-bonnet", "subtitle": "Record", "details": "Mycena adscendens is among the tiniest gilled mushrooms: a dusting of white caps only a few millimetres wide on fallen twigs and cones.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Mycena_adscendens_9244.jpg?width=1024"}, {"name": "Snowy Ink Cap", "rarity": "common", "id": "snowy-ink-cap", "subtitle": "Species", "details": "Coprinopsis nivea: Snowy Ink Cap, a white powdery inkcap growing on dung in pastures.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/2014-02-16%20Coprinopsis%20nivea%20%28Pers.%29%20Redhead%2C%20Vilgalys%20%26%20Moncalvo%20404046.jpg?width=1024"}, {"name": "Soma", "rarity": "common", "id": "soma", "subtitle": "Lore", "details": "R. Gordon Wasson proposed that soma, the sacred drink of ancient hymns, was the fly agaric; scholars still debate it.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Sprouting%20Fly%20Agarics%20%28Amanita%20muscaria%29.jpg?width=1024"}, {"name": "Sourdough Yeast", "rarity": "common", "id": "sourdough-yeast", "subtitle": "Species", "details": "Kazachstania humilis is one of the main yeasts in sourdough starters, working alongside souring bacteria.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Sourdough%20starter%20in%20a%20plastic%20tub.jpg?width=1024"}, {"name": "Split Gill", "rarity": "common", "id": "split-gill", "subtitle": "Species", "details": "Schizophyllum commune: a tiny fan whose gills split lengthwise when dry; one of the world's most widespread fungi, not eaten.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Schizophyllum%20commune%20%28Split%20gill%29%20%2833389628036%29.jpg?width=1024"}, {"name": "Spore Print", "rarity": "common", "id": "spore-print", "subtitle": "Form", "details": "A spore print is made by resting a cap on paper overnight; the colour of the fallen spore dust is a classic identification clue.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Spore_print.jpg?width=1024"}, {"name": "Spring Fieldcap", "rarity": "common", "id": "spring-fieldcap", "subtitle": "Species", "details": "Agrocybe praecox: Spring Fieldcap, a pale spring mushroom of woodchips, gardens and compost.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Agrocybe_praecox_cupertino.jpg?width=1024"}, {"name": "Stinking Brittlegill", "rarity": "common", "id": "stinking-brittlegill", "subtitle": "Species", "details": "Russula foetens: Stinking Brittlegill, a large russula with a powerful oily, fishy stench.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russula_foetens.JPG?width=1024"}, {"name": "Stubble Rosegill", "rarity": "common", "id": "stubble-rosegill", "subtitle": "Species", "details": "Volvopluteus gloiocephalus: a tall pale mushroom of compost and woodchips with pink spores; confusable with Amanita, so rarely eaten.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Volvopluteus_SoCal.jpg?width=1024"}, {"name": "Sulphur Tuft", "rarity": "common", "id": "sulphur-tuft", "subtitle": "Species", "details": "Hypholoma fasciculare: a sulphur-yellow cluster on stumps that is bitter and poisonous, causing vomiting and diarrhoea.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hypholoma%20fasciculare.%20%2810133471134%29.jpg?width=1024"}, {"name": "Teeth", "rarity": "common", "id": "spine-teeth", "subtitle": "Form", "details": "Tooth fungi bear their spores on hanging spines instead of gills or pores, like a hedgehog mushroom's brush of pale needles.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hydnum%20repandum%2002.jpg?width=1024"}, {"name": "Tempeh Mold", "rarity": "common", "id": "tempeh-mold", "subtitle": "Species", "details": "Rhizopus oligosporus binds soybeans into tempeh, the firm fermented food that originated in Indonesia.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Tempeh%20Rhizopus%20oligosporus.JPG?width=1024"}, {"name": "The Deceiver", "rarity": "common", "id": "the-deceiver", "subtitle": "Species", "details": "Laccaria laccata: a small edible mushroom so variable in colour — pink-brown to washed-out — that it earns the name deceiver.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lacc.lacc.jpg?width=1024"}, {"name": "Tiger Sawgill", "rarity": "common", "id": "tiger-sawgill", "subtitle": "Species", "details": "Lentinus tigrinus wears dark scales on a pale cap and saw-toothed gills, fruiting on dead wood in and beside rivers and floodplains.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lentinus_tigrinus.JPG?width=1024"}, {"name": "Toadstool", "rarity": "common", "id": "toadstool", "subtitle": "Lore", "details": "Toadstool is an old word for a poisonous cap fungus, from the idea of a stool fit only for toads.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita%20pantherina%204.jpg?width=1024"}, {"name": "Truffle Dog", "rarity": "common", "id": "truffle-dog", "subtitle": "Lore", "details": "The Lagotto Romagnolo, an Italian curly-coated breed, became the classic truffle dog for its nose and trainability.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Lagotto%20Romagnolo-truffle%20hunting.jpg?width=1024"}, {"name": "Tuberiform False Truffle", "rarity": "common", "id": "false-truffle-melanogaster", "subtitle": "Truffle", "details": "Melanogaster tuberiformis is an underground false truffle whose spores are spread by animals that dig it up.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Melanogaster%20tuberiformis%2017757.jpg?width=1024"}, {"name": "Twig Parachute", "rarity": "common", "id": "twig-parachute", "subtitle": "Species", "details": "Gymnopus androsaceus: the horsehair or twig parachute, a pin-sized cap on black, wiry stems in leaf litter.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Rosshaar-Blasssporr%C3%BCbling_Gymnopus_androsaceus.jpg?width=1024"}, {"name": "Two-Colored Bolete", "rarity": "common", "id": "two-colored-bolete", "subtitle": "Species", "details": "Baorangia bicolor: a red-and-yellow bolete whose pores bruise blue slowly. A popular cooked edible, but lookalikes must be ruled out.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Boletus_bicolor_89542.jpg?width=1024"}, {"name": "Universal Veil", "rarity": "common", "id": "universal-veil", "subtitle": "Form", "details": "A universal veil wraps a young mushroom completely, like an egg; it breaks as the mushroom grows, leaving a volva and cap flecks.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Phalloide-Caesarea.JPG?width=1024"}, {"name": "Velvet Roll-Rim", "rarity": "common", "id": "velvet-roll-rim", "subtitle": "Species", "details": "Tapinella atrotomentosa: a wood-rotting roll-rim with a dark, velvety, off-centre stem. Inedible and treated as poisonous.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Samtfuß-Holzkrempling_Tapinella_atrotomentosa.jpg?width=1024"}, {"name": "Vermilion Waxcap", "rarity": "common", "id": "vermilion-waxcap", "subtitle": "Species", "details": "Hygrocybe miniata: Vermilion Waxcap, a tiny scarlet waxcap brightening mossy grassland in autumn.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Hygrocybe_miniata_-_Ferndale_Park.jpg?width=1024"}, {"name": "Volva", "rarity": "common", "id": "volva", "subtitle": "Form", "details": "The volva is the cup left at a mushroom's base when it bursts from its universal veil - checking for it helps spot deadly Amanita species.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Amanita_caesarea.JPG?width=1024"}, {"name": "White Dunce Cap", "rarity": "common", "id": "white-dunce-cap", "subtitle": "Species", "details": "Conocybe apala: a tiny, milky-white lawn conecap, fragile as paper. Far too small to eat, and some of its relatives are deadly.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Conocybe_apala_Oakland.jpg?width=1024"}, {"name": "Wine Yeast", "rarity": "common", "id": "wine-yeast-torulaspora", "subtitle": "Species", "details": "Torulaspora delbrueckii is a wild yeast now used by winemakers to add aroma and complexity to wines.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Torulaspora%20delbrueckii%27s%20spores.jpg?width=1024"}, {"name": "Wine-Colored Agaricus", "rarity": "common", "id": "wine-colored-agaricus", "subtitle": "Species", "details": "Agaricus haematosarcus: a woodland Agaricus whose flesh blushes deep wine-red when cut; its edibility is not established.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Agaricus_haematosarcus_1.jpg?width=1024"}, {"name": "Winter Polypore", "rarity": "common", "id": "winter-polypore", "subtitle": "Species", "details": "Lentinus brumalis fruits through the cold months on dead hardwood sticks, a small brown cap on a central stem with white pores beneath.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Polyporus_brumalis_G3.3.jpg?width=1024"}, {"name": "Wood Woollyfoot", "rarity": "common", "id": "wood-woollyfoot", "subtitle": "Species", "details": "Gymnopus peronatus: a tough, wiry toughshank of leaf litter with a burning, peppery taste when nibbled. Inedible.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Collybia_peronata_20070812wb.JPG?width=1024"}, {"name": "Wrinkled Thimble-Cap", "rarity": "common", "id": "wrinkled-thimble-cap", "subtitle": "Species", "details": "Verpa bohemica: an early spring false morel whose wrinkled cap hangs free like a thimble. Eaten cooked by some, it upsets many stomachs.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Verpa_bohemica1.jpg?width=1024"}, {"name": "Yellow False Truffle", "rarity": "common", "id": "yellow-false-truffle", "subtitle": "Truffle", "details": "Rhizopogon luteolus, the yellow false truffle, forms pale tubers under pines and partners with their roots.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/P1050633%20Rhizopogon%20luteolus.jpg?width=1024"}, {"name": "Yellow Fieldcap", "rarity": "common", "id": "yellow-fieldcap", "subtitle": "Species", "details": "Bolbitius titubans: Yellow Fieldcap, a bright egg-yolk yellow, viscid cap on dung and rich soil.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Goldmistpilze2.jpg?width=1024"}, {"name": "Yellow Stagshorn", "rarity": "common", "id": "yellow-stagshorn", "subtitle": "Species", "details": "Calocera viscosa: a bright yellow, jelly-like stagshorn on conifer stumps; inedible and valued only for its splash of colour.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Calocera%20viscosa%2C%20Yellow%20Stagshorn%2C%20Enfield%2C%20UK.JPG?width=1024"}, {"name": "Yellow Swamp Brittlegill", "rarity": "common", "id": "yellow-swamp-brittlegill", "subtitle": "Species", "details": "Russula claroflava: a bright yellow brittlegill of bogs and damp birch woods, its gills greying with age. Listed as edible, though bland.", "image": "https://commons.wikimedia.org/wiki/Special:FilePath/Russula.claroflava.-.lindsey.jpg?width=1024"}]});
